#[cfg(test)]
mod c2e_grid_cell_loop_observer {
    use std::{cell::RefCell, time::Instant};

    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub(super) struct StorageGroups {
        pub(super) cell_vectors: u64,
        pub(super) column_vectors: u64,
        pub(super) shared_row_vectors: u64,
        pub(super) visual_bounds: u64,
        pub(super) spill_tree: u64,
    }

    impl StorageGroups {
        fn vector_bytes<T>(capacity: usize) -> u64 {
            capacity
                .saturating_mul(std::mem::size_of::<T>())
                .try_into()
                .unwrap_or(u64::MAX)
        }

        pub(super) fn from_cache(cache: &super::RootListGeometryCache) -> Self {
            Self {
                cell_vectors: Self::vector_bytes::<f32>(cache.grid_cell_widths.capacity())
                    .saturating_add(Self::vector_bytes::<f32>(
                        cache.grid_cell_heights.capacity(),
                    )),
                column_vectors: Self::vector_bytes::<f32>(cache.grid_column_x_offsets.capacity())
                    .saturating_add(Self::vector_bytes::<f32>(
                        cache.grid_column_widths.capacity(),
                    )),
                shared_row_vectors: Self::vector_bytes::<f32>(cache.row_tops.capacity())
                    .saturating_add(Self::vector_bytes::<f32>(cache.row_heights.capacity())),
                visual_bounds: Self::vector_bytes::<f32>(cache.grid_visual_row_tops.capacity())
                    .saturating_add(Self::vector_bytes::<f32>(
                        cache.grid_visual_row_bottoms.capacity(),
                    )),
                spill_tree: Self::vector_bytes::<f32>(cache.grid_visual_max_end_tree.capacity()),
            }
        }

        pub(super) fn from_capacities(
            cell_widths: usize,
            cell_heights: usize,
            column_offsets: usize,
            column_widths: usize,
            row_tops: usize,
            row_heights: usize,
            visual_tops: usize,
            visual_bottoms: usize,
            spill_tree: usize,
        ) -> Self {
            Self {
                cell_vectors: Self::vector_bytes::<f32>(cell_widths)
                    .saturating_add(Self::vector_bytes::<f32>(cell_heights)),
                column_vectors: Self::vector_bytes::<f32>(column_offsets)
                    .saturating_add(Self::vector_bytes::<f32>(column_widths)),
                shared_row_vectors: Self::vector_bytes::<f32>(row_tops)
                    .saturating_add(Self::vector_bytes::<f32>(row_heights)),
                visual_bounds: Self::vector_bytes::<f32>(visual_tops)
                    .saturating_add(Self::vector_bytes::<f32>(visual_bottoms)),
                spill_tree: Self::vector_bytes::<f32>(spill_tree),
            }
        }

        pub(super) fn total(self) -> u64 {
            self.cell_vectors
                .saturating_add(self.column_vectors)
                .saturating_add(self.shared_row_vectors)
                .saturating_add(self.visual_bounds)
                .saturating_add(self.spill_tree)
        }

        pub(super) fn overlap(self, other: Self) -> Self {
            Self {
                cell_vectors: self.cell_vectors.saturating_add(other.cell_vectors),
                column_vectors: self.column_vectors.saturating_add(other.column_vectors),
                shared_row_vectors: self
                    .shared_row_vectors
                    .saturating_add(other.shared_row_vectors),
                visual_bounds: self.visual_bounds.saturating_add(other.visual_bounds),
                spill_tree: self.spill_tree.saturating_add(other.spill_tree),
            }
        }

        pub(super) fn receipt(self, after: Self, peak: Self) -> [u64; 18] {
            let before_total = self.total();
            let after_total = after.total();
            let peak_total = peak.total();
            [
                self.cell_vectors,
                self.column_vectors,
                self.shared_row_vectors,
                self.visual_bounds,
                self.spill_tree,
                before_total,
                after.cell_vectors,
                after.column_vectors,
                after.shared_row_vectors,
                after.visual_bounds,
                after.spill_tree,
                after_total,
                peak.cell_vectors,
                peak.column_vectors,
                peak.shared_row_vectors,
                peak.visual_bounds,
                peak.spill_tree,
                peak_total,
            ]
        }
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub(super) struct Receipt {
        pub(super) calls: u64,
        pub(super) cells: u64,
        pub(super) elapsed_nanos: u64,
        pub(super) replacement_peak: Option<StorageGroups>,
    }

    thread_local! {
        static ACTIVE: RefCell<Option<Receipt>> = const { RefCell::new(None) };
    }

    pub(super) struct Scope {
        active: bool,
    }

    impl Scope {
        pub(super) fn start() -> Self {
            ACTIVE.with(|active| {
                assert!(
                    active.borrow_mut().replace(Receipt::default()).is_none(),
                    "C2-E grid cell-loop observations cannot be nested"
                );
            });
            Self { active: true }
        }

        pub(super) fn finish(mut self) -> Receipt {
            self.active = false;
            ACTIVE.with(|active| {
                active
                    .borrow_mut()
                    .take()
                    .expect("C2-E grid cell-loop scope remains installed")
            })
        }
    }

    impl Drop for Scope {
        fn drop(&mut self) {
            if self.active {
                ACTIVE.with(|active| {
                    active.borrow_mut().take();
                });
            }
        }
    }

    pub(super) fn loop_started() -> Option<Instant> {
        ACTIVE.with(|active| active.borrow().is_some().then(Instant::now))
    }

    pub(super) fn record_loop(started: Option<Instant>, cells: usize) {
        let Some(started) = started else {
            return;
        };
        let elapsed_nanos = started.elapsed().as_nanos().min(u64::MAX as u128) as u64;
        ACTIVE.with(|active| {
            let mut active = active.borrow_mut();
            let receipt = active
                .as_mut()
                .expect("a timed C2-E cell loop has an active observation scope");
            receipt.calls = receipt.calls.saturating_add(1);
            receipt.cells = receipt
                .cells
                .saturating_add(cells.try_into().unwrap_or(u64::MAX));
            receipt.elapsed_nanos = receipt.elapsed_nanos.saturating_add(elapsed_nanos);
        });
    }

    pub(super) fn record_replacement(old_cache: &super::RootListGeometryCache, new: StorageGroups) {
        ACTIVE.with(|active| {
            let mut active = active.borrow_mut();
            let Some(receipt) = active.as_mut() else {
                return;
            };
            receipt.replacement_peak = Some(StorageGroups::from_cache(old_cache).overlap(new));
        });
    }
}

#[derive(Clone, Debug, PartialEq)]
struct RootListGeometryKey {
    result_generation: u64,
    result_count: usize,
    font_revision: u64,
    width_bits: u32,
    pixels_per_point_bits: u32,
    button_font: egui::FontId,
    secondary_font: egui::FontId,
    wrap_mode: egui::TextWrapMode,
    extra_text_line_spacing_bits: u32,
    selectable_margin_x_bits: u32,
    selectable_margin_y_bits: u32,
    interaction_height_bits: u32,
    interaction_width_bits: u32,
    item_spacing_y_bits: u32,
    show_full_paths: bool,
    is_grid: bool,
    grid_columns: usize,
    grid_nominal_width_bits: u32,
    grid_spacing_x_bits: u32,
    grid_spacing_y_bits: u32,
}

/// Preserve the long-standing minimum button height across grid measurement,
/// allocation, and selected-item scrolling.
const ROOT_GRID_MIN_HEIGHT: f32 = 44.0;

fn root_selectable_frame_margin(ui: &egui::Ui) -> egui::Vec2 {
    ui.style()
        .button_style(
            &egui::widget_style::Classes::default(),
            egui::widget_style::WidgetState::Inactive,
        )
        .frame
        .total_margin()
        .sum()
}

/// Cached actual SelectableLabel row geometry for the root list.
///
/// Result contents are intentionally not retained here: a generation bump is
/// the invalidation contract for action replacement, and display-setting
/// changes invalidate the geometry key separately.
pub(super) struct RootListGeometryCache {
    key: Option<RootListGeometryKey>,
    row_tops: Vec<f32>,
    row_heights: Vec<f32>,
    row_x_offsets: Vec<f32>,
    row_response_x_offsets: Vec<f32>,
    row_widths: Vec<f32>,
    row_response_widths: Vec<f32>,
    grid_columns: usize,
    grid_nominal_width: f32,
    grid_column_x_offsets: Vec<f32>,
    grid_column_widths: Vec<f32>,
    grid_full_width: f32,
    grid_cell_widths: Vec<f32>,
    grid_cell_heights: Vec<f32>,
    grid_visual_row_tops: Vec<f32>,
    grid_visual_row_bottoms: Vec<f32>,
    grid_visual_max_end_tree: Vec<f32>,
    total_height: f32,
    content_x_offset: f32,
    content_width: f32,
    result_generation: u64,
    last_grid_mode: Option<bool>,
    popup_owner: Option<(u64, usize)>,
    popup_response: Option<egui::Response>,
    pending_popup_cleanup: Option<egui::Response>,
    #[cfg(test)]
    rebuild_count: u64,
    #[cfg(test)]
    measured_rows: u64,
    #[cfg(test)]
    measured_cells: u64,
    #[cfg(test)]
    last_rebuild_nanos: u64,
}

#[cfg(test)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct RootListGeometryObservation {
    pub(crate) rebuild_count: u64,
    pub(crate) measured_rows: u64,
    pub(crate) measured_cells: u64,
    pub(crate) last_rebuild_nanos: u64,
}

impl Default for RootListGeometryCache {
    fn default() -> Self {
        Self {
            key: None,
            row_tops: Vec::new(),
            row_heights: Vec::new(),
            row_x_offsets: Vec::new(),
            row_response_x_offsets: Vec::new(),
            row_widths: Vec::new(),
            row_response_widths: Vec::new(),
            grid_columns: 0,
            grid_nominal_width: 0.0,
            grid_column_x_offsets: Vec::new(),
            grid_column_widths: Vec::new(),
            grid_full_width: 0.0,
            grid_cell_widths: Vec::new(),
            grid_cell_heights: Vec::new(),
            grid_visual_row_tops: Vec::new(),
            grid_visual_row_bottoms: Vec::new(),
            grid_visual_max_end_tree: Vec::new(),
            total_height: 0.0,
            content_x_offset: 0.0,
            content_width: 0.0,
            result_generation: 0,
            last_grid_mode: None,
            popup_owner: None,
            popup_response: None,
            pending_popup_cleanup: None,
            #[cfg(test)]
            rebuild_count: 0,
            #[cfg(test)]
            measured_rows: 0,
            #[cfg(test)]
            measured_cells: 0,
            #[cfg(test)]
            last_rebuild_nanos: 0,
        }
    }
}

impl RootListGeometryCache {
    fn invalidate_geometry(&mut self) {
        self.key = None;
        self.row_tops.clear();
        self.row_heights.clear();
        self.row_x_offsets.clear();
        self.row_response_x_offsets.clear();
        self.row_widths.clear();
        self.row_response_widths.clear();
        self.grid_columns = 0;
        self.grid_nominal_width = 0.0;
        self.grid_column_x_offsets.clear();
        self.grid_column_widths.clear();
        self.grid_full_width = 0.0;
        self.grid_cell_widths.clear();
        self.grid_cell_heights.clear();
        self.grid_visual_row_tops.clear();
        self.grid_visual_row_bottoms.clear();
        self.grid_visual_max_end_tree.clear();
        self.total_height = 0.0;
        self.content_x_offset = 0.0;
        self.content_width = 0.0;
    }

    fn invalidate_results(&mut self) {
        self.result_generation = self.result_generation.wrapping_add(1);
        self.queue_popup_cleanup();
        self.invalidate_geometry();
    }

    pub(super) fn result_generation(&self) -> u64 {
        self.result_generation
    }

    #[cfg(feature = "qa-framebuffer-capture")]
    fn diagnostic_visible_rows(
        &self,
        visible_rows: &[usize],
        is_grid: bool,
        viewport: egui::Rect,
    ) -> Vec<VisibleRowDiagnostic> {
        visible_rows
            .iter()
            .filter_map(|&index| {
                let top = *self.row_tops.get(index)?;
                let bottom = top + *self.row_heights.get(index)?;
                let (visual_top, visual_bottom) = if is_grid {
                    (
                        *self.grid_visual_row_tops.get(index).unwrap_or(&top),
                        *self.grid_visual_row_bottoms.get(index).unwrap_or(&bottom),
                    )
                } else {
                    (top, bottom)
                };
                Some(VisibleRowDiagnostic {
                    index,
                    top,
                    bottom,
                    visual_top,
                    visual_bottom,
                    intersects_viewport: visual_bottom > viewport.min.y
                        && visual_top < viewport.max.y,
                })
            })
            .collect()
    }

    #[cfg(test)]
    pub(super) fn result_generation_for_test(&self) -> u64 {
        self.result_generation
    }

    fn observe_grid_mode(&mut self, is_grid: bool) {
        if self
            .last_grid_mode
            .replace(is_grid)
            .is_some_and(|old| old != is_grid)
        {
            self.queue_popup_cleanup();
            self.invalidate_geometry();
        }
    }

    fn queue_popup_cleanup(&mut self) {
        let pending_is_open = self
            .pending_popup_cleanup
            .as_ref()
            .is_some_and(egui::Response::context_menu_opened);
        if !pending_is_open {
            self.pending_popup_cleanup = self
                .popup_response
                .take()
                .filter(egui::Response::context_menu_opened);
        } else {
            self.popup_response = None;
        }
        self.popup_owner = None;
    }

    fn close_pending_popup(&mut self) {
        if let Some(response) = self.pending_popup_cleanup.take()
            && response.context_menu_opened()
        {
            let _ = response.context_menu(|ui| ui.close());
        }
    }

    #[cfg(test)]
    fn test_observation(&self) -> RootListGeometryObservation {
        RootListGeometryObservation {
            rebuild_count: self.rebuild_count,
            measured_rows: self.measured_rows,
            measured_cells: self.measured_cells,
            last_rebuild_nanos: self.last_rebuild_nanos,
        }
    }

    fn ensure(
        &mut self,
        ui: &egui::Ui,
        results: &[Action],
        folder_aliases: &HashMap<String, Option<String>>,
        show_full_paths: bool,
        is_grid: bool,
    ) -> bool {
        let spacing = ui.spacing();
        let text_presentation = RootResultTextPresentation::new(ui);
        let selectable_margin = root_selectable_frame_margin(ui);
        let key = RootListGeometryKey {
            result_generation: self.result_generation,
            result_count: results.len(),
            font_revision: super::font_revision::active_revision(ui.ctx()),
            width_bits: ui.available_width().to_bits(),
            pixels_per_point_bits: ui.ctx().pixels_per_point().to_bits(),
            button_font: text_presentation.primary_font.clone(),
            secondary_font: text_presentation.secondary_font.clone(),
            wrap_mode: ui.wrap_mode(),
            extra_text_line_spacing_bits: spacing.extra_text_line_spacing.to_bits(),
            selectable_margin_x_bits: selectable_margin.x.to_bits(),
            selectable_margin_y_bits: selectable_margin.y.to_bits(),
            interaction_height_bits: spacing.interact_size.y.to_bits(),
            interaction_width_bits: spacing.interact_size.x.to_bits(),
            item_spacing_y_bits: spacing.item_spacing.y.to_bits(),
            show_full_paths,
            is_grid,
            grid_columns: 0,
            grid_nominal_width_bits: 0,
            grid_spacing_x_bits: 0,
            grid_spacing_y_bits: 0,
        };
        if self.key.as_ref() == Some(&key) {
            return false;
        }

        let mut track_c_timer = crate::performance::track_c::Timer::start(
            crate::performance::track_c::Phase::RootGeometryCold,
        );
        track_c_timer.set_work_units(results.len());

        #[cfg(test)]
        let started = std::time::Instant::now();
        let width = f32::from_bits(key.width_bits);
        let spacing_y = f32::from_bits(key.item_spacing_y_bits);
        let margin = egui::vec2(
            f32::from_bits(key.selectable_margin_x_bits),
            f32::from_bits(key.selectable_margin_y_bits),
        );
        let interaction_height = spacing.interact_size.y;
        let wrap_mode = key.wrap_mode;
        let mut row_tops = Vec::with_capacity(results.len());
        let mut row_heights = Vec::with_capacity(results.len());
        let mut row_x_offsets = Vec::with_capacity(results.len());
        let mut row_response_x_offsets = Vec::with_capacity(results.len());
        let mut row_widths = Vec::with_capacity(results.len());
        let mut row_response_widths = Vec::with_capacity(results.len());
        let mut cursor_y = 0.0_f32;
        let mut content_x_offset = 0.0_f32;
        let mut content_width = width;

        for (index, action) in results.iter().enumerate() {
            if index != 0 {
                cursor_y += spacing_y;
            }
            row_tops.push(cursor_y);
            row_x_offsets.push(content_x_offset);
            row_widths.push(content_width);

            let text =
                root_list_result_text(action, folder_aliases, show_full_paths, &text_presentation);
            let size = text.measure_size_impl(
                ui.ctx(),
                ui.style(),
                egui::text::TextWrapping::from_wrap_mode_and_width(
                    wrap_mode,
                    (content_width - margin.x).max(0.0),
                ),
                egui::FontSelection::Style(egui::TextStyle::Button),
                egui::Align::Center,
            );
            let row_height = (size.y + margin.y).max(interaction_height);
            let response_width = content_width.max(size.x + margin.x);
            row_response_x_offsets.push(content_x_offset - (response_width - content_width) * 0.5);
            row_response_widths.push(response_width);
            content_x_offset -= (response_width - content_width) * 0.5;
            content_width = response_width;
            row_heights.push(row_height);
            cursor_y += row_height;
        }

        self.row_tops = row_tops;
        self.row_heights = row_heights;
        self.row_x_offsets = row_x_offsets;
        self.row_response_x_offsets = row_response_x_offsets;
        self.row_widths = row_widths;
        self.row_response_widths = row_response_widths;
        self.total_height = cursor_y;
        self.content_x_offset = content_x_offset;
        self.content_width = content_width;
        self.grid_columns = 0;
        self.grid_nominal_width = 0.0;
        self.grid_column_x_offsets.clear();
        self.grid_column_widths.clear();
        self.grid_full_width = 0.0;
        self.grid_cell_widths.clear();
        self.grid_cell_heights.clear();
        self.grid_visual_row_tops.clear();
        self.grid_visual_row_bottoms.clear();
        self.grid_visual_max_end_tree.clear();
        self.key = Some(key);
        track_c_timer.finish(crate::performance::track_c::Outcome::Completed);
        #[cfg(test)]
        {
            self.rebuild_count = self.rebuild_count.saturating_add(1);
            self.measured_rows = self
                .measured_rows
                .saturating_add(results.len().try_into().unwrap_or(u64::MAX));
            self.last_rebuild_nanos = started.elapsed().as_nanos().min(u64::MAX as u128) as u64;
        }
        true
    }

    fn ensure_grid(&mut self, ui: &egui::Ui, results: &[Action], columns: usize) -> bool {
        let spacing = ui.spacing();
        let selectable_margin = root_selectable_frame_margin(ui);
        let columns = columns.max(1);
        let grid_spacing_x = 8.0_f32;
        let grid_spacing_y = 6.0_f32;
        let width = ui.available_width();
        let nominal_width = ((width - (columns.saturating_sub(1) as f32 * grid_spacing_x))
            / columns as f32)
            .max(160.0);
        // Grid buttons are placed in a left-to-right child UI, whose default
        // text mode is Extend unless the style explicitly overrides it.
        let wrap_mode = ui.style().wrap_mode.unwrap_or(egui::TextWrapMode::Extend);
        let text_presentation = RootResultTextPresentation::new(ui);
        let key = RootListGeometryKey {
            result_generation: self.result_generation,
            result_count: results.len(),
            font_revision: super::font_revision::active_revision(ui.ctx()),
            width_bits: width.to_bits(),
            pixels_per_point_bits: ui.ctx().pixels_per_point().to_bits(),
            button_font: text_presentation.primary_font.clone(),
            secondary_font: text_presentation.secondary_font.clone(),
            wrap_mode,
            extra_text_line_spacing_bits: spacing.extra_text_line_spacing.to_bits(),
            selectable_margin_x_bits: selectable_margin.x.to_bits(),
            selectable_margin_y_bits: selectable_margin.y.to_bits(),
            interaction_height_bits: spacing.interact_size.y.to_bits(),
            interaction_width_bits: spacing.interact_size.x.to_bits(),
            item_spacing_y_bits: spacing.item_spacing.y.to_bits(),
            show_full_paths: false,
            is_grid: true,
            grid_columns: columns,
            grid_nominal_width_bits: nominal_width.to_bits(),
            grid_spacing_x_bits: grid_spacing_x.to_bits(),
            grid_spacing_y_bits: grid_spacing_y.to_bits(),
        };
        if self.key.as_ref() == Some(&key) {
            return false;
        }

        let mut track_c_timer = crate::performance::track_c::Timer::start(
            crate::performance::track_c::Phase::RootGeometryCold,
        );
        track_c_timer.set_work_units(results.len());

        #[cfg(test)]
        let started = std::time::Instant::now();
        let margin = egui::vec2(
            f32::from_bits(key.selectable_margin_x_bits),
            f32::from_bits(key.selectable_margin_y_bits),
        );
        let interaction_width = spacing.interact_size.x;
        let interaction_height = spacing.interact_size.y;
        let actual_columns = columns.min(results.len());
        let mut column_widths = vec![interaction_width; actual_columns];
        let mut cell_widths = Vec::with_capacity(results.len());
        let mut cell_heights = Vec::with_capacity(results.len());
        let mut row_heights =
            vec![interaction_height.max(ROOT_GRID_MIN_HEIGHT); results.len().div_ceil(columns)];

        #[cfg(test)]
        let cell_loop_started = c2e_grid_cell_loop_observer::loop_started();
        #[cfg(test)]
        let observe_cell_loop = cell_loop_started.is_some();
        for (index, action) in results.iter().enumerate() {
            let text = root_grid_result_text(action, &text_presentation);
            let galley = text.into_galley_impl(
                ui.ctx(),
                ui.style(),
                egui::text::TextWrapping::from_wrap_mode_and_width(
                    key.wrap_mode,
                    (nominal_width - margin.x).max(0.0),
                ),
                egui::FontSelection::Style(egui::TextStyle::Button),
                egui::Align::Center,
            );
            let cell_width = nominal_width.max(galley.size().x + margin.x);
            let cell_height = ROOT_GRID_MIN_HEIGHT
                .max(interaction_height)
                .max(galley.size().y + margin.y);
            let column = index % columns;
            let row = index / columns;
            column_widths[column] = column_widths[column].max(cell_width);
            row_heights[row] = row_heights[row].max(cell_height);
            cell_widths.push(cell_width);
            cell_heights.push(cell_height);
        }
        #[cfg(test)]
        c2e_grid_cell_loop_observer::record_loop(cell_loop_started, results.len());

        let mut column_x_offsets = Vec::with_capacity(actual_columns);
        let mut grid_full_width = 0.0_f32;
        for (index, width) in column_widths.iter().copied().enumerate() {
            if index > 0 {
                grid_full_width += grid_spacing_x;
            }
            column_x_offsets.push(grid_full_width);
            grid_full_width += width;
        }
        let content_width = cell_widths
            .iter()
            .enumerate()
            .map(|(index, width)| column_x_offsets[index % columns] + width)
            .fold(0.0_f32, f32::max);
        let mut row_tops = Vec::with_capacity(row_heights.len());
        let mut cursor_y = 0.0_f32;
        for (index, height) in row_heights.iter().copied().enumerate() {
            row_tops.push(cursor_y);
            cursor_y += height;
            if index + 1 < row_heights.len() {
                cursor_y += grid_spacing_y;
            }
        }

        // Grid centers its fixed 44pt allocation in each logical row. If the
        // actual selectable is taller, egui lets it spill below that row.
        // Keep logical prefixes for row placement and a max-end tree for
        // viewport queries, since visual row bottoms are not monotonic.
        let grid_visual_row_tops = row_tops
            .iter()
            .zip(&row_heights)
            .map(|(top, height)| top + ((height - ROOT_GRID_MIN_HEIGHT) * 0.5).max(0.0))
            .collect::<Vec<_>>();
        let grid_visual_row_bottoms = grid_visual_row_tops
            .iter()
            .zip(&row_heights)
            .map(|(top, height)| top + height)
            .collect::<Vec<_>>();
        let tree_leaves = row_heights.len().next_power_of_two().max(1);
        let mut grid_visual_max_end_tree = vec![f32::NEG_INFINITY; tree_leaves * 2];
        for (index, bottom) in grid_visual_row_bottoms.iter().copied().enumerate() {
            grid_visual_max_end_tree[tree_leaves + index] = bottom;
        }
        for index in (1..tree_leaves).rev() {
            grid_visual_max_end_tree[index] =
                grid_visual_max_end_tree[index * 2].max(grid_visual_max_end_tree[index * 2 + 1]);
        }
        let visual_bottom = grid_visual_row_bottoms
            .iter()
            .copied()
            .fold(cursor_y, f32::max);
        let empty_grid = row_heights.is_empty();

        #[cfg(test)]
        if observe_cell_loop {
            c2e_grid_cell_loop_observer::record_replacement(
                self,
                c2e_grid_cell_loop_observer::StorageGroups::from_capacities(
                    cell_widths.capacity(),
                    cell_heights.capacity(),
                    column_x_offsets.capacity(),
                    column_widths.capacity(),
                    row_tops.capacity(),
                    row_heights.capacity(),
                    grid_visual_row_tops.capacity(),
                    grid_visual_row_bottoms.capacity(),
                    grid_visual_max_end_tree.capacity(),
                ),
            );
        }

        self.row_tops = row_tops;
        self.row_heights = row_heights;
        self.row_x_offsets.clear();
        self.row_response_x_offsets.clear();
        self.row_widths.clear();
        self.row_response_widths.clear();
        self.content_x_offset = 0.0;
        self.content_width = content_width;
        self.grid_columns = columns;
        self.grid_nominal_width = nominal_width;
        self.grid_column_x_offsets = column_x_offsets;
        self.grid_column_widths = column_widths;
        self.grid_full_width = grid_full_width;
        self.grid_cell_widths = cell_widths;
        self.grid_cell_heights = cell_heights;
        self.grid_visual_row_tops = grid_visual_row_tops;
        self.grid_visual_row_bottoms = grid_visual_row_bottoms;
        self.grid_visual_max_end_tree = grid_visual_max_end_tree;
        // An empty egui Grid still lays out its centered horizontal row shell.
        self.total_height = if empty_grid {
            interaction_height * 0.5
        } else {
            visual_bottom
        };
        self.key = Some(key);
        track_c_timer.finish(crate::performance::track_c::Outcome::Completed);
        #[cfg(test)]
        {
            self.rebuild_count = self.rebuild_count.saturating_add(1);
            self.measured_cells = self
                .measured_cells
                .saturating_add(results.len().try_into().unwrap_or(u64::MAX));
            self.last_rebuild_nanos = started.elapsed().as_nanos().min(u64::MAX as u128) as u64;
        }
        true
    }

    fn visible_range(&self, viewport: egui::Rect) -> std::ops::Range<usize> {
        let mut low = 0;
        let mut high = self.row_tops.len();
        while low < high {
            let middle = low + (high - low) / 2;
            if self.row_tops[middle] + self.row_heights[middle] <= viewport.min.y {
                low = middle + 1;
            } else {
                high = middle;
            }
        }
        let end = self
            .row_tops
            .partition_point(|top| *top < viewport.max.y)
            .saturating_add(ROOT_LIST_OVERSCAN_ROWS)
            .min(self.row_tops.len());
        low.saturating_sub(ROOT_LIST_OVERSCAN_ROWS)..end
    }

    fn visible_grid_rows(&self, viewport: egui::Rect) -> Vec<usize> {
        let mut rows = self.visible_range(viewport).collect::<Vec<_>>();
        let row_count = self.grid_visual_row_tops.len();
        let visual_end = self
            .grid_visual_row_tops
            .partition_point(|top| *top < viewport.max.y);
        if row_count > 0 {
            self.collect_visual_grid_rows(
                1,
                0,
                self.grid_visual_max_end_tree.len() / 2,
                visual_end,
                viewport.min.y,
                &mut rows,
            );
        }
        rows.sort_unstable();
        rows.dedup();
        rows
    }

    fn collect_visual_grid_rows(
        &self,
        node: usize,
        start: usize,
        end: usize,
        query_end: usize,
        viewport_top: f32,
        rows: &mut Vec<usize>,
    ) {
        if start >= query_end || self.grid_visual_max_end_tree[node] <= viewport_top {
            return;
        }
        if end - start == 1 {
            if start < self.grid_visual_row_bottoms.len() {
                rows.push(start);
            }
            return;
        }
        let middle = start + (end - start) / 2;
        self.collect_visual_grid_rows(node * 2, start, middle, query_end, viewport_top, rows);
        self.collect_visual_grid_rows(node * 2 + 1, middle, end, query_end, viewport_top, rows);
    }

    fn set_popup_owner(&mut self, index: usize, response: &egui::Response) {
        self.popup_owner = Some((self.result_generation, index));
        self.popup_response = Some(response.clone());
    }

    fn popup_owner(&self) -> Option<usize> {
        self.popup_owner
            .filter(|(generation, index)| {
                *generation == self.result_generation
                    && self
                        .key
                        .as_ref()
                        .is_some_and(|key| *index < key.result_count)
            })
            .map(|(_, index)| index)
    }

    fn owned_context_menu_is_open(&self) -> bool {
        self.popup_response
            .as_ref()
            .is_some_and(egui::Response::context_menu_opened)
    }

    fn row_widget_id(&self, parent: egui::Id, index: usize) -> egui::Id {
        parent.with(("launcher-root-list-row", self.result_generation, index))
    }

    fn clear_popup_owner(&mut self) {
        self.popup_owner = None;
        self.popup_response = None;
    }
}

#[cfg(feature = "qa-framebuffer-capture")]
fn root_render_diagnostic(
    app: &LauncherApp,
    ui: &egui::Ui,
    viewport: egui::Rect,
    mode: &'static str,
    visible_rows: &[usize],
    geometry_rebuilt: bool,
) -> RootListDiagnostic {
    use std::hash::{Hash, Hasher};

    let cache = &app.root_list_geometry;
    let resolved_theme = super::theme::resolved_for_current_context(ui.ctx());
    let style_description = format!(
        "theme={resolved_theme:?};visuals={:?};text_styles={:?};fonts={:?}",
        ui.visuals(),
        ui.style().text_styles,
        cache
            .key
            .as_ref()
            .map(|key| (&key.button_font, &key.secondary_font))
    );
    let mut style_hasher = std::collections::hash_map::DefaultHasher::new();
    style_description.hash(&mut style_hasher);
    let style_identity = format!("{:016x}", style_hasher.finish());
    let rect = |rect: egui::Rect| [rect.min.x, rect.min.y, rect.max.x, rect.max.y];

    RootListDiagnostic {
        mode,
        result_count: app.results.len(),
        selected_index: app.selected.filter(|index| *index < app.results.len()),
        scroll_viewport: rect(viewport),
        content_clip: rect(ui.clip_rect()),
        content_origin: [ui.max_rect().min.x, ui.max_rect().min.y],
        scroll_inner_rect: [0.0; 4],
        content_size: [0.0; 2],
        scroll_offset: [0.0; 2],
        total_content_height: cache.total_height,
        visible_rows: cache.diagnostic_visible_rows(visible_rows, mode == "grid", viewport),
        result_generation: cache.result_generation,
        cache_key: cache
            .key
            .as_ref()
            .map_or_else(|| "missing".to_owned(), |key| format!("{key:?}")),
        geometry_rebuild_count: 0,
        rebuilt_this_frame: geometry_rebuilt,
        font_revision: super::font_revision::active_revision(ui.ctx()),
        style_identity,
        resolved_appearance: resolved_theme.map(|theme| format!("{:?}", theme.appearance)),
        overall_text_scale: resolved_theme.map(|theme| theme.metrics.body_text_size / 14.0),
        query_scale: app.query_scale,
        list_scale: app.list_scale,
        pixels_per_point: ui.ctx().pixels_per_point(),
        native_pixels_per_point: ui.ctx().native_pixels_per_point(),
        zoom_factor: ui.ctx().zoom_factor(),
    }
}

fn root_list_display_text<'a>(
    action: &'a Action,
    folder_aliases: &HashMap<String, Option<String>>,
    show_full_paths: bool,
) -> std::borrow::Cow<'a, str> {
    let aliased = folder_aliases
        .get(&action.action)
        .and_then(|alias| alias.as_ref());
    if show_full_paths || aliased.is_none() {
        std::borrow::Cow::Owned(format!("{} : {}", action.label, action.desc))
    } else {
        std::borrow::Cow::Borrowed(action.label.as_str())
    }
}

/// Font inputs and colors shared by root-result measurement and painting.
/// Resolving both roles here keeps the geometry cache aligned with the actual
/// selectable button text, including global egui font overrides.
#[derive(Clone, Debug)]
struct RootResultTextPresentation {
    primary_font: egui::FontId,
    secondary_font: egui::FontId,
    primary_line_height: f32,
    secondary_line_height: f32,
    primary_color: egui::Color32,
    secondary_color: egui::Color32,
    valign: egui::Align,
}

impl RootResultTextPresentation {
    fn new(ui: &egui::Ui) -> Self {
        let style = ui.style();
        let primary_font = egui::FontSelection::Default
            .resolve_with_fallback(style, egui::FontSelection::Style(egui::TextStyle::Button));
        let secondary_font = egui::FontSelection::Default
            .resolve_with_fallback(style, egui::FontSelection::Style(egui::TextStyle::Small));
        let override_text_color = style.visuals.override_text_color;
        let extra_line_spacing = style.spacing.extra_text_line_spacing;
        let (primary_line_height, secondary_line_height) = ui.ctx().fonts_mut(|fonts| {
            (
                fonts.row_height(&primary_font) + extra_line_spacing,
                fonts.row_height(&secondary_font) + extra_line_spacing,
            )
        });

        Self {
            primary_font,
            secondary_font,
            primary_line_height,
            secondary_line_height,
            primary_color: override_text_color.unwrap_or(egui::Color32::PLACEHOLDER),
            secondary_color: override_text_color.unwrap_or_else(|| style.visuals.weak_text_color()),
            valign: ui.text_valign(),
        }
    }

    fn widget_text(&self, primary: &str, secondary: Option<(&str, &str)>) -> egui::WidgetText {
        let primary_format = egui::text::TextFormat {
            font_id: self.primary_font.clone(),
            line_height: Some(self.primary_line_height),
            color: self.primary_color,
            valign: self.valign,
            ..Default::default()
        };
        let secondary_format = egui::text::TextFormat {
            font_id: self.secondary_font.clone(),
            line_height: Some(self.secondary_line_height),
            color: self.secondary_color,
            valign: self.valign,
            ..Default::default()
        };

        let mut job = egui::text::LayoutJob::default();
        job.append(primary, 0.0, primary_format.clone());
        if let Some((separator, secondary)) = secondary {
            job.append(separator, 0.0, primary_format);
            job.append(secondary, 0.0, secondary_format);
        }
        egui::WidgetText::from(job)
    }
}

fn root_list_result_text(
    action: &Action,
    folder_aliases: &HashMap<String, Option<String>>,
    show_full_paths: bool,
    presentation: &RootResultTextPresentation,
) -> egui::WidgetText {
    let has_alias = folder_aliases
        .get(&action.action)
        .and_then(|alias| alias.as_ref())
        .is_some();
    if show_full_paths || !has_alias {
        presentation.widget_text(&action.label, Some((" : ", &action.desc)))
    } else {
        presentation.widget_text(&action.label, None)
    }
}

fn root_grid_result_text(
    action: &Action,
    presentation: &RootResultTextPresentation,
) -> egui::WidgetText {
    presentation.widget_text(&action.label, Some(("\n", &action.desc)))
}

fn root_grid_cell_response(
    ui: &egui::Ui,
    geometry: &RootListGeometryCache,
    index: usize,
    action: &Action,
    selected: bool,
    presentation: &RootResultTextPresentation,
) -> egui::Response {
    let columns = geometry.grid_columns.max(1);
    let column = index % columns;
    let row = index / columns;
    let row_height = geometry.row_heights[row];
    let row_rect = egui::Rect::from_min_size(
        ui.max_rect().min
            + egui::vec2(
                geometry.grid_column_x_offsets[column],
                geometry.row_tops[row],
            ),
        egui::vec2(geometry.grid_column_widths[column], row_height),
    );
    let mut cell_ui = egui::Ui::new(
        ui.ctx().clone(),
        geometry.row_widget_id(ui.id(), index),
        egui::UiBuilder::new()
            .layer_id(ui.layer_id())
            .max_rect(row_rect)
            .layout(egui::Layout::left_to_right(egui::Align::Center)),
    );
    cell_ui.set_clip_rect(ui.clip_rect());
    cell_ui.set_style(ui.style().clone());
    if !ui.is_enabled() {
        cell_ui.disable();
    }
    let text = root_grid_result_text(action, presentation);
    cell_ui
        .with_layout(
            egui::Layout::left_to_right(egui::Align::Center),
            |cell_ui| {
                cell_ui.add_sized(
                    [geometry.grid_nominal_width, ROOT_GRID_MIN_HEIGHT],
                    egui::Button::selectable(selected, text).frame_when_inactive(true),
                )
            },
        )
        .inner
}

fn root_grid_row_color(row: usize, visuals: &egui::Visuals) -> Option<egui::Color32> {
    (visuals.striped && row % 2 == 1).then_some(visuals.faint_bg_color)
}

