    #[test]
    fn root_toasts_preserve_anchor_stack_hover_pause_and_configured_duration() {
        fn toast_layer(index: usize) -> egui::LayerId {
            egui::LayerId::new(
                egui::Order::Foreground,
                egui::Id::new("__toasts").with("toast").with(index),
            )
        }

        let default_context = egui::Context::default();
        let toast_bounds = LauncherApp::root_toast_region(
            egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0)),
            40.0,
            default_context
                .style_of(default_context.theme())
                .spacing
                .item_spacing,
        )
        .expect("the bounded test viewport leaves room below its header");

        fn frame(
            ctx: &egui::Context,
            app: &mut LauncherApp,
            bounds: egui::Rect,
            time: f64,
            events: Vec<egui::Event>,
        ) {
            let output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(800.0, 600.0),
                    )),
                    time: Some(time),
                    focused: true,
                    events,
                    ..Default::default()
                },
                |ui| app.render_root_toasts(ui, bounds),
            );
            output.drop_without_applying_deltas();
        }

        fn visible(ctx: &egui::Context, index: usize) -> bool {
            let layer = toast_layer(index);
            ctx.memory(|memory| memory.areas().visible_last_frame(&layer))
        }

        let ctx = egui::Context::default();
        let mut settings = Settings::default();
        settings.enable_toasts = false;
        settings.show_error_toasts = false;
        let mut app = new_app_with_settings(&ctx, settings);
        app.enable_toasts = true;
        frame(&ctx, &mut app, toast_bounds, 0.0, Vec::new());
        assert!(!visible(&ctx, 0) && !visible(&ctx, 1));

        let short_options = ToastOptions::default().duration_in_seconds(0.5);
        assert!(short_options.show_icon && short_options.show_progress);
        app.toasts.add(Toast {
            text: "long success".into(),
            kind: ToastKind::Success,
            options: ToastOptions::default().duration_in_seconds(3.0),
            style: Default::default(),
        });
        app.toasts.add(Toast {
            text: "brief failure".into(),
            kind: ToastKind::Error,
            options: short_options,
            style: Default::default(),
        });

        frame(&ctx, &mut app, toast_bounds, 0.01, Vec::new());
        // The first Area pass establishes its content size; anchor geometry is stable next frame.
        frame(&ctx, &mut app, toast_bounds, 0.02, Vec::new());
        let first = ctx
            .memory(|memory| memory.area_rect(toast_layer(0).id))
            .expect("the first toast was rendered");
        let second = ctx
            .memory(|memory| memory.area_rect(toast_layer(1).id))
            .expect("the second toast was rendered");
        assert!(visible(&ctx, 0) && visible(&ctx, 1));
        // The bounded region keeps the existing RIGHT_TOP anchor inside its inset edges.
        assert!(
            (first.right() - (toast_bounds.right() - 10.0)).abs() < 0.5,
            "{first:?}"
        );
        assert!(
            (first.top() - (toast_bounds.top() + 10.0)).abs() < 0.1,
            "{first:?}"
        );
        assert!(
            second.top() >= first.bottom() + 9.9,
            "{first:?} then {second:?}"
        );

        frame(
            &ctx,
            &mut app,
            toast_bounds,
            0.03,
            vec![egui::Event::PointerMoved(second.center())],
        );
        frame(
            &ctx,
            &mut app,
            toast_bounds,
            0.1,
            vec![egui::Event::PointerMoved(second.center())],
        );
        frame(
            &ctx,
            &mut app,
            toast_bounds,
            1.0,
            vec![egui::Event::PointerMoved(second.center())],
        );
        assert!(
            visible(&ctx, 0) && visible(&ctx, 1),
            "hovering the short toast pauses its configured half-second lifetime"
        );

        frame(
            &ctx,
            &mut app,
            toast_bounds,
            1.1,
            vec![egui::Event::PointerMoved(egui::pos2(400.0, 300.0))],
        );
        frame(&ctx, &mut app, toast_bounds, 2.0, Vec::new());
        assert!(visible(&ctx, 0) && visible(&ctx, 1));
        frame(&ctx, &mut app, toast_bounds, 2.01, Vec::new());
        assert!(visible(&ctx, 0), "the longer toast remains after expiry");
        assert!(
            !visible(&ctx, 1),
            "the short toast expires after hover ends"
        );
    }

    #[test]
    fn optional_launcher_brand_reflows_query_and_toasts_for_all_visibility_pairs() {
        fn toast_layer() -> egui::LayerId {
            egui::LayerId::new(
                egui::Order::Foreground,
                egui::Id::new("__toasts").with("toast").with(0),
            )
        }

        fn accessible_rect(
            output: &egui::FullOutput,
            predicate: impl Fn(&egui::accesskit::Node) -> bool,
            pixels_per_point: f32,
        ) -> Option<egui::Rect> {
            output
                .platform_output
                .accesskit_update
                .as_ref()?
                .nodes
                .iter()
                .filter(|(_, node)| predicate(node))
                .find_map(|(_, node)| {
                    let bounds = node.bounds()?;
                    Some(egui::Rect::from_min_max(
                        egui::pos2(
                            bounds.x0 as f32 / pixels_per_point,
                            bounds.y0 as f32 / pixels_per_point,
                        ),
                        egui::pos2(
                            bounds.x1 as f32 / pixels_per_point,
                            bounds.y1 as f32 / pixels_per_point,
                        ),
                    ))
                })
        }

        fn painted_text_rect(output: &egui::FullOutput, label: &str) -> Option<egui::Rect> {
            output.shapes.iter().find_map(|clipped| {
                if let egui::epaint::Shape::Text(text) = &clipped.shape
                    && text.galley.text() == label
                {
                    Some(text.galley.rect.translate(text.pos.to_vec2()))
                } else {
                    None
                }
            })
        }

        fn frame(
            ctx: &egui::Context,
            app: &mut LauncherApp,
            screen_rect: egui::Rect,
            time: f64,
        ) -> egui::FullOutput {
            ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(screen_rect),
                    time: Some(time),
                    focused: true,
                    ..Default::default()
                },
                |ui| app.render_root_ui(ui),
            )
        }

        let screen_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(460.0, 360.0));
        let mut query_tops = Vec::new();
        for (show_icon, show_title) in [(true, true), (true, false), (false, true), (false, false)]
        {
            let ctx = egui::Context::default();
            ctx.enable_accesskit();
            ctx.set_pixels_per_point(1.5);

            let mut settings = Settings::default();
            settings.dashboard.enabled = false;
            settings.query_scale = Some(1.35);
            settings.show_inline_errors = true;
            settings.show_launcher_icon = show_icon;
            settings.show_launcher_title = show_title;
            let mut app = new_app_with_settings(&ctx, settings);
            app.enable_toasts = true;
            app.error = Some("Optional branding diagnostic".into());
            app.focus_query = true;
            app.root_frame_logic = Some(RootFrameLogic {
                should_be_visible: true,
                just_became_visible: true,
                ..Default::default()
            });
            app.toasts.add(Toast {
                text: "Launcher header geometry notice".into(),
                kind: ToastKind::Info,
                options: ToastOptions::default().duration_in_seconds(30.0),
                style: Default::default(),
            });

            let pixels_per_point = ctx.pixels_per_point().max(f32::EPSILON);
            let brand_texture_id = crate::gui::theme::brand_texture_id(&ctx)
                .expect("the root theme loads its bundled brand icon");
            let edge_spacing = ctx.style_of(ctx.theme()).spacing.item_spacing;
            let mut settled = None;
            for time in [0.0, 0.1, 0.2] {
                let output = frame(&ctx, &mut app, screen_rect, time);
                let query_rect = accessible_rect(
                    &output,
                    |node| node.role() == egui::accesskit::Role::TextInput,
                    pixels_per_point,
                )
                .expect("the query editor remains visible in every branding mode");
                let inline_error_rect =
                    painted_text_rect(&output, "Error: Optional branding diagnostic")
                        .expect("the inline error remains visible in every branding mode");
                assert!(inline_error_rect.bottom() <= query_rect.top());
                let menu_bottom = ["File", "Settings", "Help"]
                    .into_iter()
                    .filter_map(|label| {
                        accessible_rect(
                            &output,
                            |node| node.label() == Some(label),
                            pixels_per_point,
                        )
                    })
                    .map(|rect| rect.bottom())
                    .reduce(f32::max)
                    .expect("the menu bar remains visible");
                let title_rect = painted_text_rect(&output, "Multi Launcher");
                let icon_rect = output.shapes.iter().find_map(|clipped| {
                    if let egui::epaint::Shape::Mesh(mesh) = &clipped.shape
                        && mesh.texture_id == brand_texture_id
                    {
                        Some(mesh.calc_bounds())
                    } else {
                        None
                    }
                });
                assert_eq!(title_rect.is_some(), show_title);
                assert_eq!(icon_rect.is_some(), show_icon);
                assert!(ctx.memory(|memory| memory.has_focus(egui::Id::new("query_input"))));

                let header_bottom = menu_bottom
                    .max(query_rect.bottom())
                    .max(title_rect.map_or(f32::NEG_INFINITY, |rect| rect.bottom()))
                    .max(icon_rect.map_or(f32::NEG_INFINITY, |rect| rect.bottom()));
                let bounds =
                    LauncherApp::root_toast_region(ctx.content_rect(), header_bottom, edge_spacing)
                        .expect("the narrow window retains room below the current header");
                let toast_rect = ctx
                    .memory(|memory| memory.area_rect(toast_layer().id))
                    .expect("the root toast uses the recomputed header bounds");
                assert!(bounds.contains_rect(toast_rect));
                assert!(toast_rect.top() >= header_bottom + edge_spacing.y - 0.5);

                settled = Some(query_rect.top());
                output.drop_without_applying_deltas();
            }
            query_tops.push((show_icon, show_title, settled.unwrap()));
        }

        let query_top = |icon: bool, title: bool| {
            query_tops
                .iter()
                .find_map(|(has_icon, has_title, top)| {
                    (*has_icon == icon && *has_title == title).then_some(*top)
                })
                .unwrap()
        };
        let neither = query_top(false, false);
        let icon_only = query_top(true, false);
        let title_only = query_top(false, true);
        let both = query_top(true, true);
        assert!(neither + 1.0 < title_only);
        assert!(title_only + 1.0 < icon_only);
        assert!((both - icon_only).abs() < 1.0);
    }

    #[test]
    fn root_toast_long_startup_notice_fits_below_header_and_dismisses() {
        fn toast_layer() -> egui::LayerId {
            egui::LayerId::new(
                egui::Order::Foreground,
                egui::Id::new("__toasts").with("toast").with(0),
            )
        }

        fn accessible_rect(
            output: &egui::FullOutput,
            predicate: impl Fn(&egui::accesskit::Node) -> bool,
            pixels_per_point: f32,
        ) -> Option<egui::Rect> {
            output
                .platform_output
                .accesskit_update
                .as_ref()?
                .nodes
                .iter()
                .filter(|(_, node)| predicate(node))
                .find_map(|(_, node)| {
                    let bounds = node.bounds()?;
                    Some(egui::Rect::from_min_max(
                        egui::pos2(
                            bounds.x0 as f32 / pixels_per_point,
                            bounds.y0 as f32 / pixels_per_point,
                        ),
                        egui::pos2(
                            bounds.x1 as f32 / pixels_per_point,
                            bounds.y1 as f32 / pixels_per_point,
                        ),
                    ))
                })
        }

        fn painted_text_rect(output: &egui::FullOutput, label: &str) -> Option<egui::Rect> {
            output.shapes.iter().find_map(|clipped| {
                if let egui::epaint::Shape::Text(text) = &clipped.shape
                    && text.galley.text() == label
                {
                    Some(text.visual_bounding_rect())
                } else {
                    None
                }
            })
        }

        fn painted_text_layout_rect(output: &egui::FullOutput, label: &str) -> Option<egui::Rect> {
            output.shapes.iter().find_map(|clipped| {
                if let egui::epaint::Shape::Text(text) = &clipped.shape
                    && text.galley.text() == label
                {
                    Some(text.galley.rect.translate(text.pos.to_vec2()))
                } else {
                    None
                }
            })
        }

        fn frame(
            ctx: &egui::Context,
            app: &mut LauncherApp,
            screen_rect: egui::Rect,
            time: f64,
            events: Vec<egui::Event>,
        ) -> egui::FullOutput {
            ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(screen_rect),
                    time: Some(time),
                    focused: true,
                    events,
                    ..Default::default()
                },
                |ui| app.render_root_ui(ui),
            )
        }

        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        let screen_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(400.0, 220.0));
        let mut settings = Settings::default();
        settings.dashboard.enabled = false;
        settings.enable_toasts = true;
        settings.show_error_toasts = false;
        let mut app = new_app_with_settings(&ctx, settings);
        app.enable_toasts = true;
        app.data_recovery_dialog
            .set_startup_diagnostics(vec![SafeStartupDiagnostic {
                label: "Actions startup".into(),
                path: None,
                summary: "The saved actions document needs attention.".into(),
            }]);
        let notice = app
            .data_recovery_dialog
            .take_startup_notice()
            .expect("the startup diagnostic produces one notice");
        assert_eq!(
            notice,
            "Multi Launcher started with 1 persistence diagnostic. Open Data & Recovery for details."
        );
        app.add_toast(Toast {
            text: notice.clone().into(),
            kind: ToastKind::Warning,
            options: ToastOptions::default().duration_in_seconds(30.0),
            style: Default::default(),
        });
        let mut root_frame = RootFrameLogic::default();
        root_frame.should_be_visible = true;
        app.root_frame_logic = Some(root_frame);

        let pixels_per_point = ctx.pixels_per_point().max(f32::EPSILON);
        let edge_spacing = ctx.style_of(ctx.theme()).spacing.item_spacing;
        let mut settled = None;
        for time in [0.0, 0.1, 0.2] {
            let output = frame(&ctx, &mut app, screen_rect, time, Vec::new());
            let brand_texture_id = crate::gui::theme::brand_texture_id(&ctx);
            let observation = (|| {
                let toast_rect = ctx.memory(|memory| memory.area_rect(toast_layer().id))?;
                let menu_bottom = ["File", "Settings", "Help"]
                    .into_iter()
                    .filter_map(|label| {
                        accessible_rect(
                            &output,
                            |node| node.label() == Some(label),
                            pixels_per_point,
                        )
                    })
                    .map(|rect| rect.bottom())
                    .reduce(f32::max)?;
                let brand_label_rect = painted_text_layout_rect(&output, "Multi Launcher")?;
                let brand_image_bottom = match brand_texture_id {
                    Some(texture_id) => Some(output.shapes.iter().find_map(|clipped| {
                        if let egui::epaint::Shape::Mesh(mesh) = &clipped.shape
                            && mesh.texture_id == texture_id
                        {
                            Some(mesh.calc_bounds().bottom())
                        } else {
                            None
                        }
                    })?),
                    None => None,
                };
                let brand_bottom = brand_image_bottom.map_or(brand_label_rect.bottom(), |bottom| {
                    bottom.max(brand_label_rect.bottom())
                });
                let query_rect = accessible_rect(
                    &output,
                    |node| node.role() == egui::accesskit::Role::TextInput,
                    pixels_per_point,
                )?;
                let header_bottom = menu_bottom.max(brand_bottom).max(query_rect.bottom());
                let toast_text = output.shapes.iter().find_map(|clipped| {
                    if let egui::epaint::Shape::Text(text) = &clipped.shape
                        && text.galley.text() == notice
                    {
                        Some((
                            text.visual_bounding_rect(),
                            text.galley.size(),
                            text.galley.rows.len(),
                            text.galley.elided,
                        ))
                    } else {
                        None
                    }
                })?;
                Some((toast_rect, header_bottom, toast_text))
            })();
            output.drop_without_applying_deltas();
            if let Some(observation) = observation {
                settled = Some(observation);
            }
        }

        let (toast_rect, header_bottom, (text_rect, galley_size, row_count, elided)) =
            settled.expect("the settled toast frame paints the full startup notice galley");
        let bounds =
            LauncherApp::root_toast_region(ctx.content_rect(), header_bottom, edge_spacing)
                .expect("the measured header leaves a positive toast region");
        assert!(bounds.contains_rect(toast_rect));
        assert!(toast_rect.top() >= header_bottom + edge_spacing.y);
        assert!(toast_rect.right() <= ctx.content_rect().right() - edge_spacing.x);
        assert!(toast_rect.expand(0.5).contains_rect(text_rect));
        assert!(galley_size.x <= toast_rect.width());
        assert!(row_count > 1, "the long notice wraps at the bounded width");
        assert!(!elided, "the full notice text remains in the galley");

        let click_point = text_rect.center();
        let pressed = frame(
            &ctx,
            &mut app,
            screen_rect,
            0.3,
            vec![
                egui::Event::PointerMoved(click_point),
                egui::Event::PointerButton {
                    pos: click_point,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: egui::Modifiers::default(),
                },
            ],
        );
        pressed.drop_without_applying_deltas();
        let released = frame(
            &ctx,
            &mut app,
            screen_rect,
            0.4,
            vec![egui::Event::PointerButton {
                pos: click_point,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::default(),
            }],
        );
        released.drop_without_applying_deltas();
        let closed = frame(&ctx, &mut app, screen_rect, 0.5, Vec::new());
        closed.drop_without_applying_deltas();
        assert!(
            !ctx.memory(|memory| memory.areas().visible_last_frame(&toast_layer())),
            "clicking the actual toast text dismisses it"
        );
    }

    #[derive(Clone, Debug)]
    struct EagerRootListLayout {
        rows: Vec<egui::Rect>,
        available_widths: Vec<f32>,
        bounds: egui::Rect,
    }

    fn eager_root_list_selectable_labels(
        ui: &mut egui::Ui,
        actions: &[Action],
        aliases: &HashMap<String, Option<String>>,
        show_full_paths: bool,
        outer: egui::Rect,
    ) -> EagerRootListLayout {
        let mut layout = EagerRootListLayout {
            rows: Vec::with_capacity(actions.len()),
            available_widths: Vec::with_capacity(actions.len()),
            bounds: outer,
        };
        let text_presentation = RootResultTextPresentation::new(ui);
        for action in actions {
            let text = root_list_result_text(action, aliases, show_full_paths, &text_presentation);
            let available_width = ui.available_width();
            layout.available_widths.push(available_width);
            let response = ui.add_sized(
                [available_width, 0.0],
                egui::Button::selectable(false, text).frame_when_inactive(true),
            );
            layout.bounds = layout.bounds.union(response.rect);
            layout.rows.push(response.rect);
        }
        layout
    }

    fn track_c_eager_root_list_layout(
        ctx: &egui::Context,
        actions: &[Action],
        aliases: &HashMap<String, Option<String>>,
        show_full_paths: bool,
        width: f32,
        style: &egui::Style,
        scale: f32,
    ) -> (egui::Rect, EagerRootListLayout) {
        let outer = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(width, 1_000_000.0));
        let layer = egui::LayerId::new(
            egui::Order::Foreground,
            egui::Id::new("track-c-root-list-eager-oracle"),
        );
        let mut layout = None;
        let output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(outer),
                ..Default::default()
            },
            |ctx| {
                let mut ui = test_child_ui(
                    ctx,
                    layer,
                    egui::Id::new("track-c-root-list-eager-ui"),
                    outer,
                    outer,
                );
                ui.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                    ui.set_style(style.clone());
                    scale_ui(ui, scale, |ui| {
                        layout = Some(eager_root_list_selectable_labels(
                            ui,
                            actions,
                            aliases,
                            show_full_paths,
                            outer,
                        ));
                    });
                });
            },
        );
        output.drop_without_applying_deltas();
        (outer, layout.expect("Track C eager list composition ran"))
    }

    fn assert_root_list_cache_matches_eager(
        cache: &RootListGeometryCache,
        eager: &EagerRootListLayout,
        outer: egui::Rect,
        label: &str,
    ) {
        assert_eq!(cache.row_tops.len(), eager.rows.len());
        for (index, response) in eager.rows.iter().enumerate() {
            let expected_top = response.top() - outer.top();
            assert!(
                (cache.row_tops[index] - expected_top).abs() <= 1.0,
                "{label} row {index} top: cache={} eager={expected_top}",
                cache.row_tops[index]
            );
            assert!(
                (cache.row_heights[index] - response.height()).abs() <= 1.0,
                "{label} row {index} height: cache={} eager={}",
                cache.row_heights[index],
                response.height()
            );
            assert!(
                (cache.row_widths[index] - eager.available_widths[index]).abs() <= 1.0,
                "{label} row {index} available width: cache={} eager={}",
                cache.row_widths[index],
                eager.available_widths[index]
            );
            let expected_left = response.left() - outer.left();
            assert!(
                (cache.row_response_x_offsets[index] - expected_left).abs() <= 1.0,
                "{label} row {index} response left: cache={} eager={expected_left}",
                cache.row_response_x_offsets[index]
            );
            assert!(
                (cache.row_response_widths[index] - response.width()).abs() <= 1.0,
                "{label} row {index} response width: cache={} eager={}",
                cache.row_response_widths[index],
                response.width()
            );
        }
        assert!(
            (cache.content_x_offset - (eager.bounds.left() - outer.left())).abs() <= 1.0,
            "{label} content left: cache={} eager={}",
            cache.content_x_offset,
            eager.bounds.left() - outer.left()
        );
        assert!(
            (cache.content_width - eager.bounds.width()).abs() <= 1.0,
            "{label} content width: cache={} eager={}",
            cache.content_width,
            eager.bounds.width()
        );
        assert!(
            (cache.total_height - (eager.rows.last().unwrap().bottom() - outer.top())).abs() <= 1.0,
            "{label} total height: cache={} eager={}",
            cache.total_height,
            eager.rows.last().unwrap().bottom() - outer.top()
        );
    }

    #[test]
    fn root_list_geometry_matches_eager_selectable_label_layout() {
        let cases = [
            (220.0, egui::TextWrapMode::Extend, 1.0, false, None, 0.0),
            (220.0, egui::TextWrapMode::Wrap, 1.0, false, None, 0.0),
            (420.0, egui::TextWrapMode::Wrap, 1.25, false, None, 0.0),
            (760.0, egui::TextWrapMode::Extend, 1.0, true, None, 0.0),
            (
                300.0,
                egui::TextWrapMode::Truncate,
                1.0,
                false,
                Some(egui::FontId::new(22.0, egui::FontFamily::Proportional)),
                3.5,
            ),
        ];
        let actions = vec![
            Action {
                label: format!("Unwrapped {}", "wide-path-segment/".repeat(18)),
                desc: "first overflow row".into(),
                action: "folder:wide".into(),
                args: None,
            },
            Action {
                label: "Short result".into(),
                desc: "second row follows the expanded region".into(),
                action: "test:short".into(),
                args: None,
            },
            Action {
                label: "Explicit lines\nsecond line".into(),
                desc: "Unicode e\u{301} 文雪 🧭🙂 and a moderately long wrapped description".into(),
                action: "test:multiline".into(),
                args: None,
            },
            Action {
                label: "Folder Alias".into(),
                desc: "C:\\synthetic\\folder\\with\\a\\long\\path".into(),
                action: "folder:alias".into(),
                args: None,
            },
        ];
        let aliases = HashMap::from([("folder:alias".into(), Some("Alias".into()))]);

        for (
            case_index,
            (width, wrap_mode, scale, heading_override, override_font, extra_line_spacing),
        ) in cases.into_iter().enumerate()
        {
            let ctx = egui::Context::default();
            if heading_override || override_font.is_some() || extra_line_spacing != 0.0 {
                let mut style = (*ctx.style_of(ctx.theme())).clone();
                if heading_override {
                    style.override_text_style = Some(egui::TextStyle::Heading);
                }
                style.override_font_id = override_font.clone();
                style.spacing.extra_text_line_spacing = extra_line_spacing;
                ctx.set_style_of(ctx.theme(), style);
            }
            let outer =
                egui::Rect::from_min_size(egui::pos2(31.0, 17.0), egui::vec2(width, 1_400.0));
            let layer = egui::LayerId::new(
                egui::Order::Foreground,
                egui::Id::new(("root-list-geometry-oracle", case_index)),
            );
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1_200.0, 1_500.0),
                )),
                ..Default::default()
            };
            let mut cache = RootListGeometryCache::default();
            let mut virtual_rows = Vec::new();
            let mut eager_layout = None;
            let mut measured_button_font = egui::FontId::default();
            let mut measured_secondary_font = egui::FontId::default();

            let output = ctx.run_ui(input, |ctx| {
                let mut eager = test_child_ui(
                    ctx,
                    layer,
                    egui::Id::new("root-list-eager-oracle"),
                    outer,
                    outer,
                );
                eager.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                    let mut style = ui.style().as_ref().clone();
                    style.wrap_mode = Some(wrap_mode);
                    ui.set_style(style);
                    scale_ui(ui, scale, |ui| {
                        eager_layout = Some(eager_root_list_selectable_labels(
                            ui, &actions, &aliases, false, outer,
                        ));
                    });
                });

                let mut measured = test_child_ui(
                    ctx,
                    layer,
                    egui::Id::new("root-list-geometry-cache"),
                    outer,
                    outer,
                );
                measured.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                    let mut style = ui.style().as_ref().clone();
                    style.wrap_mode = Some(wrap_mode);
                    ui.set_style(style);
                    scale_ui(ui, scale, |ui| {
                        measured_button_font = egui::FontSelection::Default.resolve_with_fallback(
                            ui.style(),
                            egui::FontSelection::Style(egui::TextStyle::Button),
                        );
                        measured_secondary_font = egui::FontSelection::Default
                            .resolve_with_fallback(
                                ui.style(),
                                egui::FontSelection::Style(egui::TextStyle::Small),
                            );
                        cache.ensure(ui, &actions, &aliases, false, false);
                        let text_presentation = RootResultTextPresentation::new(ui);
                        for (index, action) in actions.iter().enumerate() {
                            let row_rect = egui::Rect::from_min_size(
                                outer.min
                                    + egui::vec2(cache.row_x_offsets[index], cache.row_tops[index]),
                                egui::vec2(cache.row_widths[index], cache.row_heights[index]),
                            );
                            let mut row_ui = test_child_ui(
                                ctx,
                                layer,
                                cache.row_widget_id(ui.id(), index),
                                row_rect,
                                outer,
                            );
                            row_ui.set_style(ui.style().clone());
                            let text =
                                root_list_result_text(action, &aliases, false, &text_presentation);
                            let response = row_ui
                                .with_layout(
                                    egui::Layout::centered_and_justified(ui.layout().main_dir()),
                                    |row_ui| {
                                        row_ui.add(
                                            egui::Button::selectable(false, text)
                                                .frame_when_inactive(true),
                                        )
                                    },
                                )
                                .inner;
                            virtual_rows.push(response.rect);
                        }
                    });
                });
            });
            output.drop_without_applying_deltas();

            let eager_layout = eager_layout.expect("the eager selectable-label oracle ran");
            let eager_rows = &eager_layout.rows;
            let eager_available_widths = &eager_layout.available_widths;
            let eager_bounds = eager_layout.bounds;
            let key = cache.key.as_ref().expect("the cache measured its rows");
            assert_eq!(key.wrap_mode, wrap_mode);
            assert_eq!(
                key.extra_text_line_spacing_bits,
                extra_line_spacing.to_bits()
            );
            assert_eq!(key.button_font, measured_button_font);
            assert_eq!(key.secondary_font, measured_secondary_font);
            if case_index == 0 {
                assert_ne!(
                    key.button_font, key.secondary_font,
                    "result descriptions use the secondary text role by default"
                );
            } else if heading_override || override_font.is_some() {
                assert_eq!(
                    key.button_font, key.secondary_font,
                    "global style overrides retain precedence for both result sections"
                );
            }
            assert_eq!(cache.row_tops.len(), eager_rows.len());
            for (index, response) in eager_rows.iter().enumerate() {
                let expected_top = response.top() - outer.top();
                assert!(
                    (cache.row_tops[index] - expected_top).abs() <= 1.0,
                    "case {case_index} row {index} top: cache={} eager={expected_top}",
                    cache.row_tops[index]
                );
                assert!(
                    (cache.row_heights[index] - response.height()).abs() <= 1.0,
                    "case {case_index} row {index} height: cache={} eager={}",
                    cache.row_heights[index],
                    response.height()
                );
                assert!(
                    (cache.row_widths[index] - eager_available_widths[index]).abs() <= 1.0,
                    "case {case_index} row {index} available width: cache={} eager={}",
                    cache.row_widths[index],
                    eager_available_widths[index]
                );
                let expected_left = response.left() - outer.left();
                assert!(
                    (cache.row_response_x_offsets[index] - expected_left).abs() <= 1.0,
                    "case {case_index} row {index} response left: cache={} eager={expected_left}",
                    cache.row_response_x_offsets[index]
                );
                assert!(
                    (cache.row_response_widths[index] - response.width()).abs() <= 1.0,
                    "case {case_index} row {index} response width: cache={} eager={}",
                    cache.row_response_widths[index],
                    response.width()
                );
                assert!(
                    virtual_rows[index].min.distance(response.min) <= 1.0
                        && virtual_rows[index].max.distance(response.max) <= 1.0,
                    "case {case_index} row {index} constructed response differs: virtual={:?} eager={response:?}",
                    virtual_rows[index]
                );
            }
            assert!(
                (cache.content_x_offset - (eager_bounds.left() - outer.left())).abs() <= 1.0,
                "case {case_index} content left: cache={} eager={}",
                cache.content_x_offset,
                eager_bounds.left() - outer.left()
            );
            assert!(
                (cache.content_width - eager_bounds.width()).abs() <= 1.0,
                "case {case_index} content width: cache={} eager={}",
                cache.content_width,
                eager_bounds.width()
            );
            assert!(
                (cache.total_height - (eager_rows.last().unwrap().bottom() - outer.top())).abs()
                    <= 1.0,
                "case {case_index} total height: cache={} eager={}",
                cache.total_height,
                eager_rows.last().unwrap().bottom() - outer.top()
            );
        }
    }

    #[derive(Clone, Debug)]
    struct EagerRootGridLayout {
        cells: Vec<egui::Rect>,
        cell_cursors: Vec<egui::Pos2>,
        grid_bounds: egui::Rect,
        content_bounds: egui::Rect,
        nominal_width: f32,
    }

    fn eager_root_grid_layout(
        ui: &mut egui::Ui,
        actions: &[Action],
        columns: usize,
        identity: usize,
    ) -> EagerRootGridLayout {
        let nominal_width = ((ui.available_width() - columns.saturating_sub(1) as f32 * 8.0)
            / columns as f32)
            .max(160.0);
        let mut cells = Vec::with_capacity(actions.len());
        let mut cell_cursors = Vec::with_capacity(actions.len());
        let text_presentation = RootResultTextPresentation::new(ui);
        let grid = egui::Grid::new(("root-grid-real", identity))
            .num_columns(columns)
            .spacing([8.0, 6.0])
            .show(ui, |ui| {
                for (index, action) in actions.iter().enumerate() {
                    cell_cursors.push(ui.cursor().min);
                    let response = ui.add_sized(
                        [nominal_width, ROOT_GRID_MIN_HEIGHT],
                        egui::Button::selectable(
                            false,
                            root_grid_result_text(action, &text_presentation),
                        )
                        .frame_when_inactive(true),
                    );
                    cells.push(response.rect);
                    if (index + 1) % columns == 0 {
                        ui.end_row();
                    }
                }
            });
        EagerRootGridLayout {
            cells,
            cell_cursors,
            grid_bounds: grid.response.rect,
            content_bounds: ui.min_rect(),
            nominal_width,
        }
    }

    fn track_c_eager_root_grid_layout(
        ctx: &egui::Context,
        actions: &[Action],
        columns: usize,
        width: f32,
        style: &egui::Style,
        scale: f32,
    ) -> (egui::Rect, EagerRootGridLayout) {
        let outer = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(width, 1_000_000.0));
        ctx.set_style_of(ctx.theme(), style.clone());
        let layer = egui::LayerId::new(
            egui::Order::Foreground,
            egui::Id::new("track-c-root-grid-eager-oracle"),
        );
        let mut layout = None;
        for frame in 0..4 {
            let output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1_800.0, 1_500.0),
                    )),
                    time: Some(1.0 + frame as f64 / 60.0),
                    ..Default::default()
                },
                |ctx| {
                    let mut ui = test_child_ui(
                        ctx,
                        layer,
                        egui::Id::new("track-c-root-grid-eager-ui"),
                        outer,
                        outer,
                    );
                    ui.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                        ui.set_style(style.clone());
                        scale_ui(ui, scale, |ui| {
                            layout = Some(eager_root_grid_layout(ui, actions, columns, 0));
                        });
                    });
                },
            );
            output.drop_without_applying_deltas();
        }
        (outer, layout.expect("Track C eager grid composition ran"))
    }

    fn eager_grid_row_geometry(
        eager: &EagerRootGridLayout,
        columns: usize,
        outer: egui::Rect,
    ) -> Vec<(f32, f32, f32, f32)> {
        let row_count = eager.cells.len().div_ceil(columns);
        (0..row_count)
            .map(|row| {
                let first = row * columns;
                let last = (first + columns).min(eager.cells.len());
                let top = eager.cell_cursors[first].y - outer.top();
                let height = if row + 1 < row_count {
                    eager.cell_cursors[(row + 1) * columns].y - eager.cell_cursors[first].y - 6.0
                } else {
                    eager.content_bounds.bottom() - outer.top() - top
                };
                let visual_top = eager.cells[first..last]
                    .iter()
                    .map(|cell| cell.top() - outer.top())
                    .fold(f32::INFINITY, f32::min);
                let visual_bottom = eager.cells[first..last]
                    .iter()
                    .map(|cell| cell.bottom() - outer.top())
                    .fold(f32::NEG_INFINITY, f32::max);
                (top, height, visual_top, visual_bottom)
            })
            .collect()
    }

    fn assert_track_c_root_grid_matches_eager(
        cache: &RootListGeometryCache,
        eager: &EagerRootGridLayout,
        outer: egui::Rect,
        actions: &[Action],
        columns: usize,
        style: &egui::Style,
        label: &str,
    ) -> Vec<(f32, f32, f32, f32)> {
        let expected_columns = columns.min(actions.len());
        let row_geometry = eager_grid_row_geometry(eager, columns, outer);
        assert_eq!(eager.cells.len(), actions.len());
        assert_eq!(eager.cell_cursors.len(), actions.len());
        assert_eq!(cache.grid_columns, columns);
        assert_eq!(
            cache.grid_nominal_width.to_bits(),
            eager.nominal_width.to_bits()
        );
        assert_eq!(cache.grid_cell_widths.len(), actions.len());
        assert_eq!(cache.grid_cell_heights.len(), actions.len());
        assert_eq!(cache.grid_column_x_offsets.len(), expected_columns);
        assert_eq!(cache.grid_column_widths.len(), expected_columns);
        assert_eq!(cache.row_tops.len(), row_geometry.len());
        assert_eq!(cache.row_heights.len(), row_geometry.len());
        assert_eq!(cache.grid_visual_row_tops.len(), row_geometry.len());
        assert_eq!(cache.grid_visual_row_bottoms.len(), row_geometry.len());
        for row in 0..row_geometry.len() {
            let (top, height, visual_top, visual_bottom) = row_geometry[row];
            assert!(
                (cache.row_tops[row] - top).abs() <= 1.0,
                "{label} logical row {row} top: cache={} eager={top}",
                cache.row_tops[row]
            );
            assert!(
                (cache.row_heights[row] - height).abs() <= 1.0,
                "{label} logical row {row} height: cache={} eager={height}",
                cache.row_heights[row]
            );
            assert!(
                (cache.grid_visual_row_tops[row] - visual_top).abs() <= 1.0,
                "{label} visual row {row} top: cache={} eager={visual_top}",
                cache.grid_visual_row_tops[row]
            );
            assert!(
                (cache.grid_visual_row_bottoms[row] - visual_bottom).abs() <= 1.0,
                "{label} visual row {row} bottom: cache={} eager={visual_bottom}",
                cache.grid_visual_row_bottoms[row]
            );
        }

        let interaction_width = style.spacing.interact_size.x;
        let mut expected_column_widths = vec![interaction_width; expected_columns];
        for (index, cell) in eager.cells.iter().enumerate() {
            let column = index % columns;
            let expected_left = cell.left() - outer.left();
            let cell_width = cell.width().max(interaction_width);
            expected_column_widths[column] = expected_column_widths[column].max(cell_width);
            assert!(
                (cache.grid_cell_widths[index] - cell.width()).abs() <= 1.0,
                "{label} cell {index} width: cache={} eager={}",
                cache.grid_cell_widths[index],
                cell.width()
            );
            assert!(
                (cache.grid_cell_heights[index] - cell.height()).abs() <= 1.0,
                "{label} cell {index} height: cache={} eager={}",
                cache.grid_cell_heights[index],
                cell.height()
            );
            assert!(
                (cache.grid_column_x_offsets[column] - expected_left).abs() <= 1.0,
                "{label} cell {index} column offset: cache={} eager={expected_left}",
                cache.grid_column_x_offsets[column]
            );
        }
        assert!(
            cache.row_x_offsets.is_empty()
                && cache.row_response_x_offsets.is_empty()
                && cache.row_widths.is_empty()
                && cache.row_response_widths.is_empty(),
            "{label} grid cache has no stale list-row geometry"
        );
        assert_eq!(cache.content_x_offset, 0.0);
        for (column, (actual, expected)) in cache
            .grid_column_widths
            .iter()
            .zip(&expected_column_widths)
            .enumerate()
        {
            assert!(
                (actual - expected).abs() <= 1.0,
                "{label} column {column} width: cache={actual} eager={expected}"
            );
        }
        let expected_grid_width = expected_column_widths.iter().sum::<f32>()
            + expected_columns.saturating_sub(1) as f32 * 8.0;
        let expected_content_width = eager.content_bounds.right() - outer.left();
        let expected_total_height = eager.content_bounds.bottom() - outer.top();
        assert!(
            (cache.grid_full_width - expected_grid_width).abs() <= 1.0,
            "{label} full grid width: cache={} eager={expected_grid_width}",
            cache.grid_full_width
        );
        assert!(
            (cache.content_width - expected_content_width).abs() <= 1.0,
            "{label} content width: cache={} eager={expected_content_width}",
            cache.content_width
        );
        assert!(
            (cache.total_height - expected_total_height).abs() <= 1.0,
            "{label} total height: cache={} eager={expected_total_height}",
            cache.total_height
        );
        row_geometry
    }

    #[test]
    fn root_grid_geometry_matches_settled_grid_cells_and_global_extents() {
        let cases: [(
            f32,
            usize,
            f32,
            Option<egui::TextWrapMode>,
            bool,
            usize,
            Option<f32>,
            bool,
            Option<egui::FontId>,
            f32,
        ); 10] = [
            (360.0, 1, 1.0, None, false, 4, None, true, None, 0.0),
            (480.0, 2, 1.25, None, false, 9, None, true, None, 0.0),
            (
                960.0,
                3,
                1.0,
                Some(egui::TextWrapMode::Wrap),
                true,
                7,
                None,
                true,
                None,
                0.0,
            ),
            (
                230.0,
                5,
                0.9,
                Some(egui::TextWrapMode::Extend),
                false,
                3,
                None,
                true,
                None,
                0.0,
            ),
            (1_600.0, 6, 1.0, None, true, 13, None, true, None, 0.0),
            (1_600.0, 6, 1.0, None, false, 3, None, false, None, 0.0),
            (420.0, 3, 1.0, None, false, 8, Some(210.0), true, None, 0.0),
            (800.0, 3, 1.35, None, false, 0, None, false, None, 0.0),
            (800.0, 3, 1.0, None, false, 1, None, false, None, 0.0),
            (
                420.0,
                2,
                1.0,
                Some(egui::TextWrapMode::Truncate),
                false,
                4,
                None,
                true,
                Some(egui::FontId::new(21.0, egui::FontFamily::Proportional)),
                2.5,
            ),
        ];

        for (
            case_index,
            (
                width,
                columns,
                scale,
                wrap_mode,
                heading,
                count,
                interaction_width,
                wide_last,
                override_font,
                extra_line_spacing,
            ),
        ) in cases.into_iter().enumerate()
        {
            let ctx = egui::Context::default();
            if heading
                || interaction_width.is_some()
                || override_font.is_some()
                || extra_line_spacing != 0.0
            {
                let mut style = (*ctx.style_of(ctx.theme())).clone();
                if heading {
                    style.override_text_style = Some(egui::TextStyle::Heading);
                }
                style.override_font_id = override_font.clone();
                style.spacing.extra_text_line_spacing = extra_line_spacing;
                if let Some(interaction_width) = interaction_width {
                    style.spacing.interact_size.x = interaction_width;
                }
                ctx.set_style_of(ctx.theme(), style);
            }
            let actions = (0..count)
                .map(|index| Action {
                    label: if wide_last && index == count - 1 {
                        format!(
                            "Offscreen wide result {}",
                            "unwrapped/path-segment/".repeat(12)
                        )
                    } else if index == 1 {
                        "Explicit first line\nsecond line e\u{301} 文雪 🧭🙂".into()
                    } else {
                        format!("Grid result {index}")
                    },
                    desc: if index == 0 {
                        "A tall first-cell description\nwith another line and mixed Unicode 文雪 🧭🙂".into()
                    } else {
                        format!(
                            "Description for cell {index} with longer supporting details that wrap at narrow widths"
                        )
                    },
                    action: format!("test:grid-{index}"),
                    args: None,
                })
                .collect::<Vec<_>>();
            let outer =
                egui::Rect::from_min_size(egui::pos2(31.0, 17.0), egui::vec2(width, 1_400.0));
            let layer = egui::LayerId::new(
                egui::Order::Foreground,
                egui::Id::new(("root-grid-geometry-oracle", case_index)),
            );
            let mut cache = RootListGeometryCache::default();
            let mut eager_cells = Vec::new();
            let mut eager_grid_cursors = Vec::new();
            let mut eager_grid_bounds = egui::Rect::NOTHING;
            let mut eager_content_bounds = egui::Rect::NOTHING;
            let mut cached_cells = Vec::new();
            let mut interaction_size = egui::Vec2::ZERO;
            let mut measured_root_cursor = egui::Pos2::ZERO;
            let mut measured_wrap_mode = egui::TextWrapMode::Extend;
            let mut measured_button_font = egui::FontId::default();
            let mut measured_secondary_font = egui::FontId::default();

            for frame in 0..4 {
                let input = egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1_800.0, 1_500.0),
                    )),
                    time: Some(1.0 + frame as f64 / 60.0),
                    ..Default::default()
                };
                let output = ctx.run_ui(input, |ctx| {
                    let mut eager = test_child_ui(
                        ctx,
                        layer,
                        egui::Id::new("root-grid-eager-oracle"),
                        outer,
                        outer,
                    );
                    eager.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                        if let Some(wrap_mode) = wrap_mode {
                            let mut style = ui.style().as_ref().clone();
                            style.wrap_mode = Some(wrap_mode);
                            ui.set_style(style);
                        }
                        scale_ui(ui, scale, |ui| {
                            let layout = eager_root_grid_layout(ui, &actions, columns, case_index);
                            eager_grid_cursors = layout.cell_cursors;
                            eager_grid_bounds = layout.grid_bounds;
                            eager_content_bounds = layout.content_bounds;
                            eager_cells = layout.cells;
                        });
                    });

                    let mut measured = test_child_ui(
                        ctx,
                        layer,
                        egui::Id::new("root-grid-geometry-cache"),
                        outer,
                        outer,
                    );
                    measured.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                        if let Some(wrap_mode) = wrap_mode {
                            let mut style = ui.style().as_ref().clone();
                            style.wrap_mode = Some(wrap_mode);
                            ui.set_style(style);
                        }
                        scale_ui(ui, scale, |ui| {
                            measured_root_cursor = ui.cursor().min;
                            measured_wrap_mode =
                                ui.style().wrap_mode.unwrap_or(egui::TextWrapMode::Extend);
                            measured_button_font = egui::FontSelection::Default
                                .resolve_with_fallback(
                                    ui.style(),
                                    egui::FontSelection::Style(egui::TextStyle::Button),
                                );
                            measured_secondary_font = egui::FontSelection::Default
                                .resolve_with_fallback(
                                    ui.style(),
                                    egui::FontSelection::Style(egui::TextStyle::Small),
                                );
                            interaction_size = ui.spacing().interact_size;
                            cache.ensure_grid(ui, &actions, columns);
                            let text_presentation = RootResultTextPresentation::new(ui);
                            cached_cells = actions
                                .iter()
                                .enumerate()
                                .map(|(index, action)| {
                                    root_grid_cell_response(
                                        ui,
                                        &cache,
                                        index,
                                        action,
                                        false,
                                        &text_presentation,
                                    )
                                    .rect
                                })
                                .collect();
                        });
                    });
                });
                output.drop_without_applying_deltas();
            }

            assert_eq!(eager_cells.len(), actions.len());
            assert_eq!(cached_cells.len(), actions.len());
            let key = cache.key.as_ref().expect("the cache measured the grid");
            assert_eq!(key.wrap_mode, measured_wrap_mode);
            if let Some(wrap_mode) = wrap_mode {
                assert_eq!(key.wrap_mode, wrap_mode);
            }
            assert_eq!(
                key.extra_text_line_spacing_bits,
                extra_line_spacing.to_bits()
            );
            assert_eq!(key.button_font, measured_button_font);
            assert_eq!(key.secondary_font, measured_secondary_font);
            if heading || override_font.is_some() {
                assert_eq!(
                    key.button_font, key.secondary_font,
                    "global style overrides retain precedence for both grid text sections"
                );
            }
            for (index, (eager, cached)) in eager_cells.iter().zip(&cached_cells).enumerate() {
                assert!(
                    eager.min.distance(cached.min) <= 1.0 && eager.max.distance(cached.max) <= 1.0,
                    "case {case_index} cell {index}: cached={cached:?}, real Grid={eager:?}"
                );
                assert!(
                    (cache.grid_cell_widths[index] - eager.width()).abs() <= 1.0
                        && (cache.grid_cell_heights[index] - eager.height()).abs() <= 1.0,
                    "case {case_index} selected-cell extent {index}: cached={}x{}, real Grid={}x{}",
                    cache.grid_cell_widths[index],
                    cache.grid_cell_heights[index],
                    eager.width(),
                    eager.height()
                );
                let column = index % columns;
                assert!(
                    (cache.grid_column_x_offsets[column] - (eager.left() - outer.left())).abs()
                        <= 1.0,
                    "case {case_index} cell {index} global column offset differs"
                );
                let row = index / columns;
                let expected_row_top = eager_grid_cursors[index].y - outer.top();
                assert!(
                    (cache.row_tops[row] - expected_row_top).abs() <= 1.0,
                    "case {case_index} cell {index} global row offset differs: cache={} expected={} eager={eager:?} grid_cursor={:?} root_cursor={measured_root_cursor:?}",
                    cache.row_tops[row],
                    expected_row_top,
                    eager_grid_cursors[index],
                );
            }
            for row in 0..cache.row_tops.len() {
                let row_start = row * columns;
                let row_end = (row_start + columns).min(eager_cells.len());
                let actual_visual_top = eager_cells[row_start..row_end]
                    .iter()
                    .map(|rect| rect.top() - outer.top())
                    .fold(f32::INFINITY, f32::min);
                let actual_visual_bottom = eager_cells[row_start..row_end]
                    .iter()
                    .map(|rect| rect.bottom() - outer.top())
                    .fold(f32::NEG_INFINITY, f32::max);
                assert!(
                    (cache.grid_visual_row_tops[row] - actual_visual_top).abs() <= 1.0,
                    "case {case_index} visual row {row} top: cached={} eager={actual_visual_top}",
                    cache.grid_visual_row_tops[row]
                );
                assert!(
                    (cache.grid_visual_row_bottoms[row] - actual_visual_bottom).abs() <= 1.0,
                    "case {case_index} visual row {row} bottom: cached={} eager={actual_visual_bottom}",
                    cache.grid_visual_row_bottoms[row]
                );
            }
            let expected_columns = columns.min(actions.len());
            assert_eq!(cache.grid_column_widths.len(), expected_columns);
            for column in 0..expected_columns {
                let actual_width = eager_cells
                    .iter()
                    .enumerate()
                    .filter(|(index, _)| index % columns == column)
                    .map(|(_, rect)| rect.width().max(interaction_size.x))
                    .fold(0.0_f32, f32::max);
                assert!(
                    (cache.grid_column_widths[column] - actual_width).abs() <= 1.0,
                    "case {case_index} column {column}: cached={} real Grid={actual_width}",
                    cache.grid_column_widths[column]
                );
            }
            let expected_height = eager_content_bounds.bottom() - outer.top();
            assert!(
                (cache.total_height - expected_height).abs() <= 1.0,
                "case {case_index} total height: cached={} Grid response={eager_grid_bounds:?} content min_rect={eager_content_bounds:?} expected={expected_height} row_tops={:?} row_heights={:?}",
                cache.total_height,
                cache.row_tops,
                cache.row_heights,
            );
            let expected_width = (0..expected_columns)
                .map(|column| {
                    eager_cells
                        .iter()
                        .enumerate()
                        .filter(|(index, _)| index % columns == column)
                        .map(|(_, rect)| rect.width().max(interaction_size.x))
                        .fold(0.0_f32, f32::max)
                })
                .sum::<f32>()
                + expected_columns.saturating_sub(1) as f32 * 8.0;
            assert!(
                (cache.content_width - (eager_content_bounds.right() - outer.left())).abs() <= 1.0,
                "case {case_index} actual content width: cached={} real Grid content min_rect={eager_content_bounds:?}",
                cache.content_width,
            );
            assert!(
                (cache.grid_full_width - expected_width).abs() <= 1.0,
                "case {case_index} Grid full width: cached={} derived={expected_width}",
                cache.grid_full_width
            );
            assert!(
                (eager_grid_bounds.width() - eager_content_bounds.width()).abs() <= 1.0,
                "case {case_index} Grid response/content min_rect widths differ: response={}, min_rect={}",
                eager_grid_bounds.width(),
                eager_content_bounds.width(),
            );
            if case_index == 5 {
                assert!(
                    expected_width < width,
                    "short partial grid has no phantom columns"
                );
            }
        }
    }

    #[test]
    fn root_grid_tall_cell_spill_stays_visible_without_intermediate_rows() {
        let ctx = egui::Context::default();
        let actions = (0..300)
            .map(|index| Action {
                label: if index == 0 {
                    "Tall cell\n".repeat(150)
                } else {
                    format!("Grid result {index}")
                },
                desc: format!("Description {index}"),
                action: format!("test:grid-spill-{index}"),
                args: None,
            })
            .collect::<Vec<_>>();
        let outer = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(480.0, 1_400.0));
        let layer = egui::LayerId::new(
            egui::Order::Foreground,
            egui::Id::new("root-grid-tall-cell-spill"),
        );
        let mut cache = RootListGeometryCache::default();
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(1_800.0, 1_500.0),
            )),
            time: Some(1.0),
            ..Default::default()
        };
        let output = ctx.run_ui(input, |ctx| {
            let mut ui = test_child_ui(
                ctx,
                layer,
                egui::Id::new("root-grid-tall-cell-cache"),
                outer,
                outer,
            );
            ui.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                cache.ensure_grid(ui, &actions, 3);
            });
        });
        output.drop_without_applying_deltas();

        let row_height = cache.row_heights[0];
        let viewport_top = row_height * 1.25;
        assert!(viewport_top < cache.grid_visual_row_bottoms[0]);
        let viewport =
            egui::Rect::from_min_size(egui::pos2(0.0, viewport_top), egui::vec2(480.0, 80.0));
        assert!(!cache.visible_range(viewport).contains(&0));

        let rows = cache.visible_grid_rows(viewport);
        assert!(rows.contains(&0), "the tall cell is still visually visible");
        assert!(rows.len() < 10, "visible rows stay bounded: {rows:?}");
        assert!(
            rows.get(1).is_some_and(|next| *next > 1),
            "invisible logical rows are not added just to bridge a spill: {rows:?}"
        );
    }

    fn root_list_test_app(
        ctx: &egui::Context,
        results: Vec<Action>,
    ) -> (
        crate::performance::workloads::IsolatedWorkspace,
        LauncherApp,
    ) {
        let workspace = crate::performance::workloads::IsolatedWorkspace::new();
        let app = root_list_app_at(ctx, results, workspace.root());
        (workspace, app)
    }

    fn root_list_app_at(
        ctx: &egui::Context,
        results: Vec<Action>,
        root: &std::path::Path,
    ) -> LauncherApp {
        let mut settings = Settings::default();
        settings.hotkey = None;
        settings.quit_hotkey = None;
        settings.help_hotkey = None;
        settings.enable_toasts = false;
        settings.show_inline_errors = false;
        settings.show_error_toasts = false;
        settings.dashboard.enabled = false;
        settings.pinned_panels.clear();
        let mut app = LauncherApp::new(
            ctx,
            Arc::new(Vec::new()),
            0,
            PluginManager::new_inert_for_test(),
            root.join("actions.json").to_string_lossy().into_owned(),
            root.join("settings.json").to_string_lossy().into_owned(),
            settings,
            None,
            None,
            Some(std::collections::HashSet::new()),
            Some(HashMap::new()),
            Arc::new(AtomicBool::new(false)),
            Arc::new(AtomicBool::new(false)),
            Arc::new(AtomicBool::new(false)),
        );
        // The first root frame otherwise starts the production dashboard's
        // all-sources refresh even though the dashboard is disabled. This
        // isolated observer fixture intentionally keeps that worker dormant.
        app.dashboard_initial_refresh_queued = true;
        app.actions = Arc::new(results.clone());
        app.results = results;
        app.invalidate_root_list_results();
        app.query = "root list fixture".into();
        app.last_search_query = app.query.clone();
        app.last_results_valid = true;
        app.pending_query = None;
        app.background_query_refresh_pending = false;
        app.last_plugin_search_generation = app.plugins.search_generation();
        app.query_results_layout.enabled = false;
        app.recompute_query_results_layout();
        app.list_scale = 1.0;
        app.selected = None;
        app
    }

    fn root_list_action(index: usize) -> Action {
        Action {
            label: format!("Launcher result {index}"),
            desc: if index.is_multiple_of(7) {
                format!("A longer description for row {index} with some wrapped words")
            } else {
                "Synthetic root row".into()
            },
            action: format!("app:root-list-{index}"),
            args: Some(format!("argument-{index}")),
        }
    }

    fn run_root_list_frame(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        frame_index: usize,
        width: f32,
        height: f32,
        events: Vec<egui::Event>,
    ) -> egui::FullOutput {
        run_root_list_frame_with_pass_count(ctx, app, frame_index, width, height, events).0
    }

    fn run_root_list_frame_with_pass_count(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        frame_index: usize,
        width: f32,
        height: f32,
        events: Vec<egui::Event>,
    ) -> (egui::FullOutput, usize) {
        run_root_list_frame_with_optional_phase_times(
            ctx,
            app,
            frame_index,
            width,
            height,
            events,
            None,
        )
    }

    fn run_root_list_frame_with_phase_times(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        frame_index: usize,
        width: f32,
        height: f32,
        events: Vec<egui::Event>,
        phase_times: &mut TestRootFramePhaseTimes,
    ) -> (egui::FullOutput, usize) {
        run_root_list_frame_with_optional_phase_times(
            ctx,
            app,
            frame_index,
            width,
            height,
            events,
            Some(phase_times),
        )
    }

    fn run_root_list_frame_with_optional_phase_times(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        frame_index: usize,
        width: f32,
        height: f32,
        events: Vec<egui::Event>,
        phase_times: Option<&mut TestRootFramePhaseTimes>,
    ) -> (egui::FullOutput, usize) {
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(width, height),
            )),
            time: Some(1.0 + frame_index as f64 / 60.0),
            events,
            ..Default::default()
        };
        match phase_times {
            Some(phase_times) => app.run_root_frame_for_test_with_phase_times(
                ctx,
                input,
                false,
                |app, ui| app.render_root_ui(ui),
                phase_times,
            ),
            None => app.run_root_frame_for_test(ctx, input, false),
        }
    }

    fn assert_retained_immediate_viewport(ctx: &egui::Context, viewport_id: egui::ViewportId) {
        let (parent_id, input_id, immediate, root_ui_min_rect) =
            ctx.viewport_for(viewport_id, |viewport| {
                (
                    viewport
                        .input
                        .raw
                        .viewports
                        .get(&viewport_id)
                        .and_then(|info| info.parent),
                    viewport.input.raw.viewport_id,
                    viewport.viewport_ui_cb.is_none(),
                    viewport.prev_pass.root_ui_min_rect,
                )
            });
        assert!(
            immediate,
            "egui retained an immediate viewport registration"
        );
        assert_eq!(parent_id, Some(egui::ViewportId::ROOT));
        assert_eq!(input_id, viewport_id);
        assert!(root_ui_min_rect.is_some(), "child root UI was retained");
        assert_eq!(ctx.viewport_id(), egui::ViewportId::ROOT);
    }

    fn arm_track_c_frame_sample(app: &mut LauncherApp, invocation_id: u64) -> u64 {
        use crate::visibility::VisibilityToggleBatch;

        let mut batch = VisibilityToggleBatch::default();
        let (was_visible, revision) = batch.record_toggle_ordered_with_invocation(
            &app.visibility_revision,
            &app.visible_flag,
            Some(invocation_id),
        );
        assert!(!was_visible, "the fixture begins hidden");
        app.track_c_test_force_enabled = true;
        // The test uses the production render/completion path while explicitly
        // seeding its revision-owned timer independent of the process switch.
        app.visibility_revision
            .arm_first_usable_frame_for_test(revision, Some(invocation_id));
        revision
    }

    #[test]
    fn app_setup_registers_font_revision_before_a_discarded_first_pass() {
        let ctx = egui::Context::default();
        let (workspace, _app) = root_list_test_app(&ctx, Vec::new());
        let mut definitions = egui::FontDefinitions::default();
        definitions
            .families
            .get_mut(&egui::FontFamily::Proportional)
            .expect("default proportional family exists")
            .push("Ubuntu-Light".into());
        let mut passes = 0;
        let output = ctx.run_ui(egui::RawInput::default(), |ui| {
            if passes == 0 {
                assert_eq!(crate::gui::font_revision::active_revision(ui.ctx()), 0);
                crate::gui::font_revision::install(ui.ctx(), definitions.clone());
                ui.ctx()
                    .request_discard("font revision lifecycle regression");
            } else {
                assert_eq!(crate::gui::font_revision::active_revision(ui.ctx()), 1);
            }
            passes += 1;
        });
        output.drop_without_applying_deltas();

        assert!(passes >= 2, "the in-pass install forced a subsequent pass");
        assert_eq!(crate::gui::font_revision::active_revision(&ctx), 1);
        drop(_app);
        drop(workspace);
    }

