    fn settle_root_selection(
        ctx: &egui::Context,
        app: &mut LauncherApp,
        next_frame: &mut usize,
        selected: usize,
    ) {
        app.selected = Some(selected);
        for _ in 0..30 {
            let frame = *next_frame;
            *next_frame += 1;
            run_root_list_frame(ctx, app, frame, 960.0, 640.0, Vec::new())
                .drop_without_applying_deltas();
        }
        assert_eq!(app.selected, Some(selected));
    }

    #[test]
    fn root_list_viewport_builds_bounded_rows_with_absolute_ids_and_selection() {
        let ctx = egui::Context::default();
        let (workspace, mut app) = root_list_test_app(&ctx, Vec::new());
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;
        let mut frame = 0;

        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        assert!(app.test_root_rendered_rows.is_empty());

        app.actions = Arc::new(vec![root_list_action(0)]);
        app.results = (*app.actions).clone();
        app.invalidate_root_list_results();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(app.test_root_rendered_rows.len(), 1);
        assert_eq!(app.test_root_rendered_rows[0].0, 0);

        let results = (0..10_000).map(root_list_action).collect::<Vec<_>>();
        let expected_ids = results
            .iter()
            .map(|action| action.action.clone())
            .collect::<Vec<_>>();
        app.actions = Arc::new(results.clone());
        app.results = results;
        app.invalidate_root_list_results();

        let mut first_id = None;
        for selected in [0, 5_000, 9_999, 0] {
            settle_root_selection(&ctx, &mut app, &mut frame, selected);
            let rows = &app.test_root_rendered_rows;
            let ids = &app.test_root_rendered_row_ids;
            assert!(!rows.is_empty());
            assert!(rows.len() <= 64, "built {} rows", rows.len());
            assert_eq!(ids.len(), rows.len());
            assert!(rows.windows(2).all(|pair| pair[0].0 < pair[1].0));
            for (index, action_id) in rows {
                assert_eq!(app.results[*index].action, *action_id);
                assert_eq!(app.results[*index].action, expected_ids[*index]);
            }
            assert_eq!(
                rows.iter().filter(|(index, _)| *index == selected).count(),
                1
            );
            let viewport = app.test_root_scroll_viewport_rect.unwrap();
            let selected_rect = app
                .test_root_rendered_row_rects
                .iter()
                .find_map(|(index, rect)| (*index == selected).then_some(*rect))
                .expect("the selected list row has a real response rectangle");
            assert!(
                viewport.contains_rect(selected_rect),
                "selected list row {selected} must be fully visible: row={selected_rect:?}, viewport={viewport:?}"
            );
            let selected_id = ids
                .iter()
                .find_map(|(index, id)| (*index == selected).then_some(*id))
                .expect("the settled selected row is constructed");
            if selected == 0 {
                if let Some(previous) = first_id {
                    assert_eq!(selected_id, previous, "absolute row identity is stable");
                }
                first_id = Some(selected_id);
            }
        }
        drop(app);
        drop(workspace);
    }

    #[test]
    fn root_result_text_job_preserves_explicit_color_override_for_both_roles() {
        let ctx = egui::Context::default();
        let override_color = egui::Color32::from_rgb(213, 47, 181);
        let mut section_colors = Vec::new();
        let output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(320.0, 200.0),
                )),
                ..Default::default()
            },
            |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| {
                    let mut style = (**ui.style()).clone();
                    style.visuals.override_text_color = Some(override_color);
                    ui.set_style(style);

                    let presentation = RootResultTextPresentation::new(ui);
                    let egui::WidgetText::LayoutJob(job) =
                        presentation.widget_text("Primary", Some((" : ", "Secondary")))
                    else {
                        panic!("prepared result text remains a layout job");
                    };
                    section_colors = job
                        .sections
                        .iter()
                        .map(|section| section.format.color)
                        .collect();
                });
            },
        );
        output.drop_without_applying_deltas();

        assert_eq!(
            section_colors,
            vec![override_color, override_color],
            "explicit visual text color applies to both primary and secondary sections"
        );
    }

    #[test]
    fn root_list_geometry_rebuilds_only_when_layout_or_display_inputs_change() {
        let ctx = egui::Context::default();
        let mut actions = (0..32).map(root_list_action).collect::<Vec<_>>();
        actions[0].action = "folder:root-list-alias".into();
        let (workspace, mut app) = root_list_test_app(&ctx, actions);
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;
        let mut frame = 0;

        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        let mut rebuilds = app.root_list_geometry.test_observation().rebuild_count;
        assert_eq!(rebuilds, 1);
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.root_list_geometry.test_observation().rebuild_count,
            rebuilds
        );

        let mut expect_rebuild = |app: &LauncherApp| {
            rebuilds += 1;
            assert_eq!(
                app.root_list_geometry.test_observation().rebuild_count,
                rebuilds
            );
        };
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        app.list_scale = 1.2;
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        let mut style = (*ctx.style_of(ctx.theme())).clone();
        let mut expected_primary_font = style
            .text_styles
            .get(&egui::TextStyle::Button)
            .expect("the button text role exists")
            .clone();
        expected_primary_font.size *= app.list_scale;
        let mut secondary_font = style
            .text_styles
            .get(&egui::TextStyle::Small)
            .expect("the small text role exists")
            .clone();
        secondary_font.size += 2.0;
        style
            .text_styles
            .insert(egui::TextStyle::Small, secondary_font.clone());
        ctx.set_style_of(ctx.theme(), style);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().secondary_font,
            egui::FontId::new(
                secondary_font.size * app.list_scale,
                secondary_font.family.clone(),
            ),
            "changing only the secondary result font rebuilds list geometry"
        );
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().button_font,
            expected_primary_font,
            "changing the secondary result font leaves the primary font unchanged"
        );

        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.override_text_style = Some(egui::TextStyle::Heading);
        ctx.set_style_of(ctx.theme(), style);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        let override_font = egui::FontId::new(19.0, egui::FontFamily::Proportional);
        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.override_font_id = Some(override_font.clone());
        ctx.set_style_of(ctx.theme(), style.clone());
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().button_font,
            override_font
        );

        let prior_rebuilds = app.root_list_geometry.test_observation().rebuild_count;
        style.override_text_style = Some(egui::TextStyle::Monospace);
        ctx.set_style_of(ctx.theme(), style.clone());
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.root_list_geometry.test_observation().rebuild_count,
            prior_rebuilds,
            "override_font_id takes precedence over text-style overrides"
        );

        let resized_override_font = egui::FontId::new(22.0, egui::FontFamily::Proportional);
        style.override_font_id = Some(resized_override_font.clone());
        ctx.set_style_of(ctx.theme(), style.clone());
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().button_font,
            resized_override_font
        );

        style.spacing.extra_text_line_spacing = 2.75;
        ctx.set_style_of(ctx.theme(), style.clone());
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_eq!(
            app.root_list_geometry
                .key
                .as_ref()
                .unwrap()
                .extra_text_line_spacing_bits,
            2.75_f32.to_bits()
        );

        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.wrap_mode = Some(egui::TextWrapMode::Truncate);
        ctx.set_style_of(ctx.theme(), style);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().wrap_mode,
            egui::TextWrapMode::Truncate
        );

        ctx.set_pixels_per_point(1.25);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        app.folder_aliases.insert(
            "folder:root-list-alias".into(),
            Some("Fixture folder".into()),
        );
        app.invalidate_root_list_display_geometry();
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        app.enabled_capabilities = Some(HashMap::from([(
            "folders".into(),
            vec!["show_full_path".into()],
        )]));
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        let prior_id = app.test_root_rendered_row_ids[0].1;
        app.results[0].label = "Same-length replacement action label".into();
        app.invalidate_root_list_results();
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_ne!(app.test_root_rendered_row_ids[0].1, prior_id);

        app.query_results_layout.enabled = true;
        app.recompute_query_results_layout();
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.query_results_layout.enabled = false;
        app.recompute_query_results_layout();
        let prior_rebuilds = app.root_list_geometry.test_observation().rebuild_count;
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        assert_eq!(
            app.root_list_geometry.test_observation().rebuild_count,
            prior_rebuilds + 1,
            "returning from grid mode rebuilds list geometry"
        );
        drop(app);
        drop(workspace);
    }

    #[test]
    fn root_list_and_grid_geometry_follow_consumer_font_activation() {
        let ctx = egui::Context::default();
        let (workspace, mut app) =
            root_list_test_app(&ctx, (0..12).map(root_list_action).collect());
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;

        let changed_definitions = |copies: usize| {
            let mut definitions = egui::FontDefinitions::default();
            let family = definitions
                .families
                .get_mut(&egui::FontFamily::Proportional)
                .expect("default proportional family exists");
            let existing_face = family[0].clone();
            for _ in 0..copies {
                family.push(existing_face.clone());
            }
            definitions
        };
        let first_replacement = changed_definitions(1);
        let second_replacement = changed_definitions(2);
        let default_definitions = egui::FontDefinitions::default();
        let mut frame = 0;
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let action_count = app.results.len() as u64;
        let initial = app.root_list_geometry.test_observation();
        assert_eq!(initial.rebuild_count, 1);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().font_revision,
            0
        );

        let run_frame_with_installs =
            |app: &mut LauncherApp, frame_index: usize, installs: &[egui::FontDefinitions]| {
                let output = app
                    .run_root_frame_for_test_with(
                        &ctx,
                        egui::RawInput {
                            screen_rect: Some(egui::Rect::from_min_size(
                                egui::Pos2::ZERO,
                                egui::vec2(960.0, 640.0),
                            )),
                            time: Some(1.0 + frame_index as f64 / 60.0),
                            ..Default::default()
                        },
                        false,
                        |app, ui| {
                            app.render_root_ui(ui);
                            for definitions in installs {
                                crate::gui::font_revision::install(ui.ctx(), definitions.clone());
                            }
                        },
                    )
                    .0;
                output.drop_without_applying_deltas();
            };

        run_frame_with_installs(&mut app, frame, std::slice::from_ref(&default_definitions));
        frame += 1;
        assert_eq!(crate::gui::font_revision::active_revision(&ctx), 0);
        assert_eq!(app.root_list_geometry.test_observation(), initial);

        run_frame_with_installs(
            &mut app,
            frame,
            &[first_replacement.clone(), default_definitions],
        );
        frame += 1;
        assert_eq!(crate::gui::font_revision::active_revision(&ctx), 0);
        assert_eq!(app.root_list_geometry.test_observation(), initial);
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(crate::gui::font_revision::active_revision(&ctx), 0);
        assert_eq!(app.root_list_geometry.test_observation(), initial);

        run_frame_with_installs(&mut app, frame, &[first_replacement]);
        frame += 1;
        assert_eq!(crate::gui::font_revision::active_revision(&ctx), 0);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().font_revision,
            0,
            "an in-pass request leaves the already measured geometry valid"
        );
        assert_eq!(app.root_list_geometry.test_observation(), initial);
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let list_active_revision = crate::gui::font_revision::active_revision(&ctx);
        assert!(list_active_revision > 0);
        let after_list_activation = app.root_list_geometry.test_observation();
        assert_eq!(
            after_list_activation.rebuild_count,
            initial.rebuild_count + 1
        );
        assert_eq!(
            after_list_activation.measured_rows - initial.measured_rows,
            action_count
        );
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().font_revision,
            list_active_revision
        );
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.root_list_geometry.test_observation(),
            after_list_activation,
            "the next unchanged list frame reuses the font-revision geometry"
        );

        app.query_results_layout.enabled = true;
        app.query_results_layout.cols = 3;
        app.query_results_layout.respect_plugin_capability = false;
        app.recompute_query_results_layout();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let before_grid_activation = app.root_list_geometry.test_observation();
        assert!(app.root_list_geometry.key.as_ref().unwrap().is_grid);

        run_frame_with_installs(&mut app, frame, &[second_replacement]);
        frame += 1;
        assert_eq!(
            crate::gui::font_revision::active_revision(&ctx),
            list_active_revision
        );
        assert_eq!(
            app.root_list_geometry.test_observation(),
            before_grid_activation
        );
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().font_revision,
            list_active_revision,
            "grid measurement keeps the font revision active at its own pass"
        );
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let grid_active_revision = crate::gui::font_revision::active_revision(&ctx);
        assert!(grid_active_revision > list_active_revision);
        let after_grid_activation = app.root_list_geometry.test_observation();
        assert_eq!(
            after_grid_activation.rebuild_count,
            before_grid_activation.rebuild_count + 1
        );
        assert_eq!(
            after_grid_activation.measured_cells - before_grid_activation.measured_cells,
            action_count
        );
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().font_revision,
            grid_active_revision
        );
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        assert_eq!(
            app.root_list_geometry.test_observation(),
            after_grid_activation,
            "the next unchanged grid frame reuses the activated geometry"
        );
        frame += 1;

        let mut palette_theme = crate::settings::ThemeSettings {
            mode: crate::settings::ThemeMode::Custom,
            ..crate::settings::ThemeSettings::default()
        };
        palette_theme.custom_scheme = crate::settings::ColorScheme::dark();
        palette_theme.custom_scheme.text = crate::settings::ThemeColor {
            r: 233,
            g: 221,
            b: 201,
            a: 255,
        };
        let before_palette_change = app.root_list_geometry.test_observation();
        assert!(crate::gui::theme::publish_committed(&ctx, &palette_theme));
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.root_list_geometry.test_observation(),
            before_palette_change,
            "palette-only updates reuse grid geometry"
        );

        let mut density_theme = palette_theme.clone();
        density_theme.preferences.density = crate::settings::ThemeDensity::Comfortable;
        assert!(crate::gui::theme::publish_committed(&ctx, &density_theme));
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let after_density_change = app.root_list_geometry.test_observation();
        assert_eq!(
            after_density_change.rebuild_count,
            before_palette_change.rebuild_count + 1,
            "density changes rebuild grid geometry once"
        );
        assert_eq!(
            after_density_change.measured_cells - before_palette_change.measured_cells,
            action_count
        );
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.root_list_geometry.test_observation(),
            after_density_change,
            "unchanged density reuses the rebuilt grid geometry"
        );

        app.query_results_layout.enabled = false;
        app.recompute_query_results_layout();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let before_typography_change = app.root_list_geometry.test_observation();
        let mut typography_theme = density_theme;
        typography_theme.preferences.typography_scale = 1.25;
        assert!(crate::gui::theme::publish_committed(
            &ctx,
            &typography_theme
        ));
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let after_typography_change = app.root_list_geometry.test_observation();
        assert_eq!(
            after_typography_change.rebuild_count,
            before_typography_change.rebuild_count + 1,
            "typography changes rebuild list geometry once"
        );
        assert_eq!(
            after_typography_change.measured_rows - before_typography_change.measured_rows,
            action_count
        );
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        assert_eq!(
            app.root_list_geometry.test_observation(),
            after_typography_change,
            "unchanged typography reuses the rebuilt list geometry"
        );
        app.list_scale = 1.25;
        for overall_scale in [0.75, 1.0, 2.0] {
            let mut combined_theme = typography_theme.clone();
            combined_theme.preferences.typography_scale = overall_scale;
            assert!(crate::gui::theme::publish_committed(&ctx, &combined_theme));
            run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
                .drop_without_applying_deltas();
            frame += 1;
            let key = app.root_list_geometry.key.as_ref().unwrap();
            assert!(
                (key.button_font.size - 14.0 * overall_scale * app.list_scale).abs() < 0.01,
                "list-local scaling composes with overall typography once: actual={}, overall={overall_scale}, local={}",
                key.button_font.size,
                app.list_scale
            );
            let observation = app.root_list_geometry.test_observation();
            run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
                .drop_without_applying_deltas();
            frame += 1;
            assert_eq!(
                app.root_list_geometry.test_observation(),
                observation,
                "unchanged combined font scaling reuses list geometry"
            );
        }

        drop(app);
        drop(workspace);
    }

    #[test]
    fn root_list_context_menu_owner_stays_with_its_absolute_row_offscreen() {
        let ctx = egui::Context::default();
        let results = (0..120).map(root_list_action).collect::<Vec<_>>();
        let (workspace, mut app) = root_list_test_app(&ctx, results);
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;
        let mut frame = 0;
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        let row_zero = app
            .test_root_rendered_row_rects
            .iter()
            .find_map(|(index, rect)| (*index == 0).then_some(*rect))
            .expect("the initial viewport contains the first result");
        let pointer = row_zero.center();
        let pressed = vec![
            egui::Event::PointerMoved(pointer),
            egui::Event::PointerButton {
                pos: pointer,
                button: egui::PointerButton::Secondary,
                pressed: true,
                modifiers: egui::Modifiers::NONE,
            },
        ];
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, pressed)
            .drop_without_applying_deltas();
        frame += 1;
        let released = vec![
            egui::Event::PointerMoved(pointer),
            egui::Event::PointerButton {
                pos: pointer,
                button: egui::PointerButton::Secondary,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            },
        ];
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, released)
            .drop_without_applying_deltas();
        frame += 1;
        assert!(
            egui::Popup::is_any_open(&ctx),
            "the secondary click opened a menu"
        );
        assert_eq!(app.root_list_geometry.popup_owner(), Some(0));
        let old_row_id = app
            .test_root_rendered_row_ids
            .iter()
            .find_map(|(index, id)| (*index == 0).then_some(*id))
            .expect("the popup owner remains constructed");
        let scroll_id = app.test_root_scroll_area_id.unwrap();
        let mut scroll_state = egui::scroll_area::State::load(&ctx, scroll_id).unwrap();
        scroll_state.offset.y = app.root_list_geometry.row_tops[80];
        scroll_state.store(&ctx, scroll_id);

        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(app.root_list_geometry.popup_owner(), Some(0));
        assert!(egui::Popup::is_any_open(&ctx));
        assert!(
            app.test_root_rendered_rows
                .iter()
                .any(|(index, _)| *index == 0)
        );
        assert!(app.test_root_rendered_rows.len() <= 64);
        assert_eq!(
            app.test_root_rendered_row_ids
                .iter()
                .find_map(|(index, id)| (*index == 0).then_some(*id)),
            Some(old_row_id)
        );

        let replacement = (0..120)
            .map(|index| Action {
                label: format!("Replacement {index}"),
                desc: "replacement result".into(),
                action: format!("app:replacement-{index}"),
                args: None,
            })
            .collect::<Vec<_>>();
        app.results = replacement.clone();
        app.actions = Arc::new(replacement);
        app.invalidate_root_list_results();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        assert_eq!(app.root_list_geometry.popup_owner(), None);
        assert!(
            !egui::Popup::is_any_open(&ctx),
            "the obsolete root popup is closed"
        );
        assert!(
            app.test_root_rendered_row_ids
                .iter()
                .all(|(_, id)| *id != old_row_id)
        );
        drop(app);
        drop(workspace);
    }

    #[test]
    fn root_grid_viewport_builds_complete_bounded_rows_with_absolute_ids_and_click_targets() {
        let _lock = MACRO_ACTIVATION_TEST_MUTEX.lock().unwrap();
        set_execute_action_hook(Some(Box::new(|_| Ok(()))));
        struct ResetExecuteHook;
        impl Drop for ResetExecuteHook {
            fn drop(&mut self) {
                set_execute_action_hook(None);
            }
        }
        let _reset_hook = ResetExecuteHook;

        let ctx = egui::Context::default();
        let results = (0..10_000)
            .map(|index| {
                let mut action = root_list_action(index);
                action.action = format!("exec:root-grid-{index}");
                action
            })
            .collect::<Vec<_>>();
        let expected_ids = results
            .iter()
            .map(|action| action.action.clone())
            .collect::<Vec<_>>();
        let (workspace, mut app) = root_list_test_app(&ctx, Vec::new());
        app.query_results_layout.enabled = true;
        app.query_results_layout.cols = 3;
        app.query_results_layout.respect_plugin_capability = false;
        app.recompute_query_results_layout();
        assert!(app.resolved_grid_layout);
        // Keep the root fixture alive after synthetic external-action clicks;
        // the hook isolates command execution but normal UI outcome policies
        // still run after activation.
        app.clear_query_after_run = false;
        app.hide_after_run = false;
        app.visible_flag.store(true, Ordering::SeqCst);

        let mut frame = 0;
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        assert!(app.test_root_rendered_rows.is_empty());
        assert!(app.root_list_geometry.row_tops.is_empty());
        assert!(app.root_list_geometry.grid_column_widths.is_empty());

        let single = Action {
            label: "Single grid cell".into(),
            desc: "No placeholder columns".into(),
            action: "exec:root-grid-single".into(),
            args: None,
        };
        app.actions = Arc::new(vec![single.clone()]);
        app.results = vec![single];
        app.invalidate_root_list_results();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.test_root_rendered_rows,
            vec![(0, "exec:root-grid-single".into())]
        );
        assert_eq!(app.root_list_geometry.grid_column_widths.len(), 1);
        assert_eq!(app.root_list_geometry.grid_cell_widths.len(), 1);

        app.actions = Arc::new(results.clone());
        app.results = results;
        app.invalidate_root_list_results();

        let mut first_cell_id = None;
        for selected in [0, 5_000, 9_999, 0] {
            settle_root_selection(&ctx, &mut app, &mut frame, selected);
            let rows = &app.test_root_rendered_rows;
            let ids = &app.test_root_rendered_row_ids;
            assert!(!rows.is_empty());
            assert!(rows.len() <= 64, "built {} grid cells", rows.len());
            assert_eq!(ids.len(), rows.len());
            assert!(rows.windows(2).all(|pair| pair[0].0 < pair[1].0));
            assert!(rows.iter().all(|(index, action_id)| {
                app.results
                    .get(*index)
                    .is_some_and(|action| action.action == *action_id)
                    && *action_id == expected_ids[*index]
            }));
            let first_row = rows[0].0 / 3;
            let last_row = rows.last().unwrap().0 / 3;
            for row in first_row..=last_row {
                let row_indices = rows
                    .iter()
                    .filter_map(|(index, _)| (*index / 3 == row).then_some(*index))
                    .collect::<Vec<_>>();
                let row_start = row * 3;
                let row_end = (row_start + 3).min(app.results.len());
                assert_eq!(
                    row_indices,
                    (row_start..row_end).collect::<Vec<_>>(),
                    "grid viewport constructs complete absolute row {row}"
                );
            }
            assert_eq!(
                rows.iter().filter(|(index, _)| *index == selected).count(),
                1,
                "selected cell is built exactly once"
            );
            let viewport = app.test_root_scroll_viewport_rect.unwrap();
            let selected_rect = app
                .test_root_rendered_row_rects
                .iter()
                .find_map(|(index, rect)| (*index == selected).then_some(*rect))
                .expect("the selected grid cell has a real response rectangle");
            assert!(
                selected_rect.top() >= viewport.top()
                    && selected_rect.bottom() <= viewport.bottom()
                    && selected_rect.intersects(viewport),
                "selected grid cell {selected} must be vertically visible and horizontally intersecting: cell={selected_rect:?}, viewport={viewport:?}"
            );
            let selected_id = ids
                .iter()
                .find_map(|(index, id)| (*index == selected).then_some(*id))
                .expect("settled selected cell is constructed");
            if selected == 0 {
                if let Some(previous) = first_cell_id {
                    assert_eq!(selected_id, previous, "absolute cell identity is stable");
                }
                first_cell_id = Some(selected_id);
            }
        }

        for target in [0, 9_999] {
            app.selected = None;
            let scroll_id = app.test_root_scroll_area_id.unwrap();
            let mut state = egui::scroll_area::State::load(&ctx, scroll_id).unwrap();
            let (inner_rect, content_size, _) = app.test_root_scroll_area_extent.unwrap();
            let max_scroll = (content_size.y - inner_rect.height()).max(0.0);
            state.offset.y = if target == 0 { 0.0 } else { max_scroll };
            state.store(&ctx, scroll_id);
            for _ in 0..30 {
                run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
                    .drop_without_applying_deltas();
                frame += 1;
            }
            let target_rect = app
                .test_root_rendered_row_rects
                .iter()
                .find_map(|(index, rect)| (*index == target).then_some(*rect))
                .expect("the first and distant final grid cells are hit-testable");
            let viewport = app.test_root_scroll_viewport_rect.unwrap();
            let scroll_state = egui::scroll_area::State::load(&ctx, scroll_id).unwrap();
            let (inner_rect, content_size, _) = app.test_root_scroll_area_extent.unwrap();
            let max_scroll = (content_size.y - inner_rect.height()).max(0.0);
            let pointer = target_rect.center();
            assert!(
                inner_rect.contains_rect(target_rect)
                    && viewport.intersects(target_rect)
                    && viewport.contains(pointer),
                "target {target} must be inside the scroll viewport before click: cell={target_rect:?}, clip={viewport:?}, inner_rect={inner_rect:?}, scroll_area={:?}, scroll_offset={}, expected_max={max_scroll}, content_size={content_size:?}, cache_height={}",
                app.test_root_scroll_area_extent,
                scroll_state.offset.y,
                app.root_list_geometry.total_height,
            );
            run_root_list_frame(
                &ctx,
                &mut app,
                frame,
                960.0,
                640.0,
                vec![egui::Event::PointerMoved(pointer)],
            )
            .drop_without_applying_deltas();
            frame += 1;
            let pressed = vec![egui::Event::PointerButton {
                pos: pointer,
                button: egui::PointerButton::Primary,
                pressed: true,
                modifiers: egui::Modifiers::NONE,
            }];
            run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, pressed)
                .drop_without_applying_deltas();
            frame += 1;
            let released = vec![egui::Event::PointerButton {
                pos: pointer,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            }];
            run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, released)
                .drop_without_applying_deltas();
            frame += 1;
            assert_eq!(
                app.selected,
                Some(target),
                "target {target} click at {pointer:?} in {target_rect:?}; clip={:?}, scroll_area={:?}, visible={}, query={:?}, results={}, last activation={:?}, rendered rows={:?}",
                app.test_root_scroll_viewport_rect,
                app.test_root_scroll_area_extent,
                app.visible_flag.load(Ordering::SeqCst),
                app.query,
                app.results.len(),
                app.test_last_activation,
                app.test_root_rendered_rows
            );
            assert_eq!(
                app.test_last_activation
                    .as_ref()
                    .map(|(action, _)| action.action.as_str()),
                Some(expected_ids[target].as_str()),
                "pointer dispatch targets the absolute cell action"
            );
            assert_eq!(
                app.test_last_activation.as_ref().map(|(_, source)| *source),
                Some(ActivationSource::Click),
                "the real root-cell response dispatches as a click"
            );
        }
        drop(app);
        drop(workspace);
    }

    #[test]
    fn root_grid_geometry_reuses_warm_cache_and_tracks_grid_layout_inputs() {
        let ctx = egui::Context::default();
        let (workspace, mut app) =
            root_list_test_app(&ctx, (0..48).map(root_list_action).collect::<Vec<_>>());
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;
        app.query_results_layout.enabled = true;
        app.query_results_layout.cols = 3;
        app.query_results_layout.respect_plugin_capability = false;
        app.recompute_query_results_layout();
        let mut frame = 0;
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        let mut rebuilds = app.root_list_geometry.test_observation().rebuild_count;
        assert!(rebuilds > 0);
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(
            app.root_list_geometry.test_observation().rebuild_count,
            rebuilds
        );

        let mut expect_rebuild = |app: &LauncherApp| {
            rebuilds += 1;
            assert_eq!(
                app.root_list_geometry.test_observation().rebuild_count,
                rebuilds
            );
        };
        app.query_results_layout.cols = 4;
        app.recompute_query_results_layout();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        app.list_scale = 1.15;
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.override_text_style = Some(egui::TextStyle::Heading);
        ctx.set_style_of(ctx.theme(), style);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.wrap_mode = Some(egui::TextWrapMode::Truncate);
        ctx.set_style_of(ctx.theme(), style);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        ctx.set_pixels_per_point(1.25);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        app.results[0].label.push_str(" replacement");
        app.actions = Arc::new(app.results.clone());
        app.invalidate_root_list_results();
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        app.query_results_layout.enabled = false;
        app.recompute_query_results_layout();
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        app.query_results_layout.enabled = true;
        app.recompute_query_results_layout();
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        expect_rebuild(&app);

        let paints_fill = |output: &egui::FullOutput, color| {
            output.shapes.iter().any(|clipped| {
                matches!(
                    &clipped.shape,
                    egui::Shape::Rect(rect) if rect.fill == color
                )
            })
        };
        let first_palette_color = egui::Color32::from_rgb(231, 23, 143);
        let second_palette_color = egui::Color32::from_rgb(17, 219, 167);
        let mut visuals = ctx.style_of(ctx.theme()).visuals.clone();
        visuals.striped = true;
        visuals.faint_bg_color = first_palette_color;
        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.visuals = visuals.clone();
        ctx.set_style_of(ctx.theme(), style);
        let palette_observation = app.root_list_geometry.test_observation();
        let palette_revision = crate::gui::font_revision::active_revision(&ctx);
        let first_output = run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new());
        assert!(
            paints_fill(&first_output, first_palette_color),
            "the actual grid frame paints the active stripe color"
        );
        first_output.drop_without_applying_deltas();
        assert_eq!(
            app.root_list_geometry.test_observation(),
            palette_observation
        );
        assert_eq!(
            crate::gui::font_revision::active_revision(&ctx),
            palette_revision
        );
        frame += 1;

        visuals.faint_bg_color = second_palette_color;
        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.visuals = visuals;
        ctx.set_style_of(ctx.theme(), style);
        let second_output = run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new());
        assert!(
            paints_fill(&second_output, second_palette_color),
            "a palette-only change reaches the actual grid paint output"
        );
        assert!(!paints_fill(&second_output, first_palette_color));
        second_output.drop_without_applying_deltas();
        assert_eq!(
            app.root_list_geometry.test_observation(),
            palette_observation
        );
        assert_eq!(
            crate::gui::font_revision::active_revision(&ctx),
            palette_revision
        );

        frame += 1;
        let mut style = (*ctx.style_of(ctx.theme())).clone();
        style.override_text_style = None;
        ctx.set_style_of(ctx.theme(), style.clone());
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);

        let mut expected_primary_font = style
            .text_styles
            .get(&egui::TextStyle::Button)
            .expect("the button text role exists")
            .clone();
        expected_primary_font.size *= app.list_scale;
        let mut secondary_font = style
            .text_styles
            .get(&egui::TextStyle::Small)
            .expect("the small text role exists")
            .clone();
        secondary_font.size += 2.0;
        style
            .text_styles
            .insert(egui::TextStyle::Small, secondary_font.clone());
        ctx.set_style_of(ctx.theme(), style);
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        expect_rebuild(&app);
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().secondary_font,
            egui::FontId::new(
                secondary_font.size * app.list_scale,
                secondary_font.family.clone(),
            ),
            "changing only the secondary result font rebuilds the measured grid once"
        );
        assert_eq!(
            app.root_list_geometry.key.as_ref().unwrap().button_font,
            expected_primary_font,
            "changing the secondary result font leaves the primary font unchanged"
        );
        run_root_list_frame(&ctx, &mut app, frame, 820.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        assert_eq!(
            app.root_list_geometry.test_observation().rebuild_count,
            rebuilds,
            "the secondary-font geometry is reused warm"
        );

        let mut visuals = egui::Visuals::dark();
        visuals.striped = true;
        assert_eq!(root_grid_row_color(0, &visuals), None);
        assert_eq!(
            root_grid_row_color(1, &visuals),
            Some(visuals.faint_bg_color)
        );
        assert_eq!(root_grid_row_color(2, &visuals), None);
        visuals.striped = false;
        assert_eq!(root_grid_row_color(1, &visuals), None);
        drop(app);
        drop(workspace);
    }

    #[test]
    fn root_grid_popup_owner_retains_complete_row_without_retargeting() {
        let ctx = egui::Context::default();
        let results = (0..120).map(root_list_action).collect::<Vec<_>>();
        let (workspace, mut app) = root_list_test_app(&ctx, results);
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;
        app.query_results_layout.enabled = true;
        app.query_results_layout.cols = 3;
        app.query_results_layout.respect_plugin_capability = false;
        app.recompute_query_results_layout();
        let mut frame = 0;
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        app.dashboard_data_cache.wait_for_refresh();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        let row_zero = app
            .test_root_rendered_row_rects
            .iter()
            .find_map(|(index, rect)| (*index == 0).then_some(*rect))
            .expect("initial viewport includes the first grid cell");
        let pointer = row_zero.center();
        let pressed = vec![
            egui::Event::PointerMoved(pointer),
            egui::Event::PointerButton {
                pos: pointer,
                button: egui::PointerButton::Secondary,
                pressed: true,
                modifiers: egui::Modifiers::NONE,
            },
        ];
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, pressed)
            .drop_without_applying_deltas();
        frame += 1;
        let released = vec![
            egui::Event::PointerMoved(pointer),
            egui::Event::PointerButton {
                pos: pointer,
                button: egui::PointerButton::Secondary,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            },
        ];
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, released)
            .drop_without_applying_deltas();
        frame += 1;
        assert!(egui::Popup::is_any_open(&ctx));
        assert_eq!(app.root_list_geometry.popup_owner(), Some(0));
        let old_row_id = app
            .test_root_rendered_row_ids
            .iter()
            .find_map(|(index, id)| (*index == 0).then_some(*id))
            .expect("the popup-owning cell has an absolute ID");

        let scroll_id = app.test_root_scroll_area_id.unwrap();
        let mut scroll_state = egui::scroll_area::State::load(&ctx, scroll_id).unwrap();
        scroll_state.offset.y = app.root_list_geometry.row_tops[25];
        scroll_state.store(&ctx, scroll_id);
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        frame += 1;
        assert_eq!(app.root_list_geometry.popup_owner(), Some(0));
        assert!(egui::Popup::is_any_open(&ctx));
        for index in 0..3 {
            assert!(
                app.test_root_rendered_rows
                    .iter()
                    .any(|(built, _)| *built == index),
                "popup owner retains complete row zero"
            );
        }
        assert!(app.test_root_rendered_rows.len() <= 64);
        assert_eq!(
            app.test_root_rendered_row_ids
                .iter()
                .find_map(|(index, id)| (*index == 0).then_some(*id)),
            Some(old_row_id)
        );

        let replacement = (0..120)
            .map(|index| Action {
                label: format!("Replacement {index}"),
                desc: "replacement result".into(),
                action: format!("app:replacement-{index}"),
                args: None,
            })
            .collect::<Vec<_>>();
        app.results = replacement.clone();
        app.actions = Arc::new(replacement);
        app.invalidate_root_list_results();
        run_root_list_frame(&ctx, &mut app, frame, 960.0, 640.0, Vec::new())
            .drop_without_applying_deltas();
        assert_eq!(app.root_list_geometry.popup_owner(), None);
        assert!(
            !egui::Popup::is_any_open(&ctx),
            "the old row menu closes on replacement"
        );
        assert!(
            app.test_root_rendered_row_ids
                .iter()
                .all(|(_, id)| *id != old_row_id)
        );
        drop(app);
        drop(workspace);
    }

    #[test]
    #[ignore = "opt-in Track A workload benchmark; set MULTI_LAUNCHER_PERF=1 before the process"]
    fn track_a_benchmark_launcher_root_rows() {
        use crate::performance::{Metric, workloads};
        use std::cell::{Cell, RefCell};

        let workspace = workloads::IsolatedWorkspace::new();
        let context = egui::Context::default();
        let mut settings = Settings::default();
        settings.enable_toasts = false;
        settings.show_inline_errors = false;
        settings.show_error_toasts = false;
        settings.dashboard.enabled = false;
        settings.hotkey = None;
        settings.quit_hotkey = None;
        settings.help_hotkey = None;
        let root = workspace.root();

        for count in workloads::selected_sizes(&[100, 1_000, 10_000]) {
            let fixture = workloads::action_fixture(0x4c41_554e_4348_4552, count);
            let mut app = LauncherApp::new(
                &context,
                Arc::new(Vec::new()),
                0,
                PluginManager::new_inert_for_test(),
                root.join("actions.json").to_string_lossy().into_owned(),
                root.join("settings.json").to_string_lossy().into_owned(),
                settings.clone(),
                None,
                None,
                Some(std::collections::HashSet::new()),
                None,
                Arc::new(AtomicBool::new(false)),
                Arc::new(AtomicBool::new(false)),
                Arc::new(AtomicBool::new(false)),
            );
            app.dashboard_initial_refresh_queued = true;
            app.actions = Arc::new(fixture.values.clone());
            app.results = fixture.values.clone();
            app.invalidate_root_list_results();
            app.query = "synthetic launcher fixture".into();
            app.last_search_query = app.query.clone();
            app.last_results_valid = true;
            app.pending_query = None;
            app.background_query_refresh_pending = false;
            app.last_plugin_search_generation = app.plugins.search_generation();
            app.list_scale = 1.0;
            app.query_results_layout.enabled = false;
            app.recompute_query_results_layout();

            let expected_ids = fixture
                .values
                .iter()
                .map(|action| action.action.clone())
                .collect::<Vec<_>>();
            let frame_index = Cell::new(0_usize);
            for (selection_index, selected) in [0, count / 2, count - 1].into_iter().enumerate() {
                app.selected = Some(selected);
                for settle_frame in 0..30 {
                    let frame = frame_index.get();
                    frame_index.set(frame + 1);
                    let input = egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(960.0, 640.0),
                        )),
                        time: Some(1.0 + frame as f64 / 60.0),
                        ..Default::default()
                    };
                    app.run_root_frame_for_test(&context, input, false)
                        .0
                        .drop_without_applying_deltas();
                    if selection_index == 0 && settle_frame == 0 {
                        app.dashboard_data_cache.wait_for_refresh();
                    }
                }
                assert_eq!(app.selected, Some(selected));
                assert_eq!(app.results[selected].action, expected_ids[selected]);
                assert_eq!(app.results.len(), count);
                assert!(
                    app.test_root_rendered_rows
                        .windows(2)
                        .all(|pair| pair[0].0 < pair[1].0)
                );
                assert!(
                    app.test_root_rendered_rows
                        .iter()
                        .all(|(index, action_id)| {
                            app.results
                                .get(*index)
                                .is_some_and(|action| action.action == *action_id)
                        })
                );
                assert_eq!(
                    app.test_root_rendered_rows
                        .iter()
                        .filter(|(index, action_id)| {
                            *index == selected && action_id == &expected_ids[selected]
                        })
                        .count(),
                    1,
                    "selection scroll should build the selected result exactly once"
                );
            }
            let cold_geometry = app.root_list_geometry.test_observation();
            assert!(cold_geometry.rebuild_count > 0);
            assert!(cold_geometry.measured_rows >= count as u64);
            app.dashboard_data_cache.wait_for_refresh();

            for (scenario, grid) in [("list", false), ("grid-3-column", true)] {
                let geometry_before_mode = app.root_list_geometry.test_observation();
                app.query_results_layout.enabled = grid;
                app.query_results_layout.cols = 3;
                app.query_results_layout.respect_plugin_capability = false;
                app.recompute_query_results_layout();
                assert_eq!(app.resolved_grid_layout, grid);
                for selected in [0, count / 2, count - 1] {
                    app.selected = Some(selected);
                    for _ in 0..30 {
                        let frame = frame_index.get();
                        frame_index.set(frame + 1);
                        let input = egui::RawInput {
                            screen_rect: Some(egui::Rect::from_min_size(
                                egui::Pos2::ZERO,
                                egui::vec2(960.0, 640.0),
                            )),
                            time: Some(1.0 + frame as f64 / 60.0),
                            ..Default::default()
                        };
                        app.run_root_frame_for_test(&context, input, false)
                            .0
                            .drop_without_applying_deltas();
                    }
                    assert_eq!(app.selected, Some(selected));
                    assert_eq!(app.results[selected].action, expected_ids[selected]);
                    assert!(
                        app.test_root_rendered_rows
                            .windows(2)
                            .all(|pair| pair[0].0 < pair[1].0)
                    );
                    assert!(
                        app.test_root_rendered_rows
                            .iter()
                            .all(|(index, action_id)| {
                                app.results
                                    .get(*index)
                                    .is_some_and(|action| action.action == *action_id)
                            })
                    );
                    assert_eq!(
                        app.test_root_rendered_rows
                            .iter()
                            .filter(|(index, action_id)| {
                                *index == selected && action_id == &expected_ids[selected]
                            })
                            .count(),
                        1,
                        "selection scroll should build the selected result exactly once"
                    );
                }
                let mode_geometry = app.root_list_geometry.test_observation();
                if grid {
                    assert!(
                        mode_geometry
                            .measured_cells
                            .saturating_sub(geometry_before_mode.measured_cells)
                            >= count as u64,
                        "cold grid geometry measures every fixture cell"
                    );
                }
                app.selected = Some(count / 2);
                for _ in 0..30 {
                    let frame = frame_index.get();
                    frame_index.set(frame + 1);
                    let input = egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(960.0, 640.0),
                        )),
                        time: Some(1.0 + frame as f64 / 60.0),
                        ..Default::default()
                    };
                    app.run_root_frame_for_test(&context, input, false)
                        .0
                        .drop_without_applying_deltas();
                }
                let geometry_before = app.root_list_geometry.test_observation();

                let input_slot = RefCell::new(None);
                let (timing, _frame_output) = workloads::measure(
                    workloads::UI_WARMUPS,
                    |_, _| {
                        let frame = frame_index.get();
                        frame_index.set(frame + 1);
                        *input_slot.borrow_mut() = Some(egui::RawInput {
                            screen_rect: Some(egui::Rect::from_min_size(
                                egui::Pos2::ZERO,
                                egui::vec2(960.0, 640.0),
                            )),
                            time: Some(1.0 + frame as f64 / 60.0),
                            ..Default::default()
                        });
                    },
                    || {
                        let input = input_slot
                            .borrow_mut()
                            .take()
                            .expect("setup creates deterministic raw input");
                        app.run_root_frame_for_test(&context, input, false).0
                    },
                );
                let metrics = workloads::metrics_for(&[Metric::LauncherRowsBuilt]);
                let geometry_after = app.root_list_geometry.test_observation();
                assert_eq!(metrics.len(), 1);
                assert_eq!(metrics[0].calls, workloads::SAMPLE_COUNT as u64);
                assert!(!app.test_root_rendered_rows.is_empty());
                assert_eq!(
                    metrics[0].work_units,
                    (app.test_root_rendered_rows.len() * workloads::SAMPLE_COUNT) as u64,
                    "row counter tracks actual list/grid widget constructions"
                );
                assert_eq!(
                    app.results.len(),
                    count,
                    "rendering cannot replace fixture results"
                );
                assert_eq!(app.selected, Some(count / 2));
                assert_eq!(app.results[count / 2].action, expected_ids[count / 2]);

                let mut signature = workloads::StableSignature::new(
                    0,
                    "launcher-output-order",
                    app.test_root_rendered_rows.len(),
                );
                let mut membership = app
                    .test_root_rendered_rows
                    .iter()
                    .map(|(index, action_id)| (*index, action_id.as_str()))
                    .collect::<Vec<_>>();
                membership.sort_unstable_by(|a, b| a.1.cmp(b.1));
                let mut membership_signature = workloads::StableSignature::new(
                    0,
                    "launcher-output-membership",
                    membership.len(),
                );
                for (index, action_id) in &app.test_root_rendered_rows {
                    let action = &app.results[*index];
                    signature.number(*index as u64);
                    signature.bytes(action_id.as_bytes());
                    signature.bytes(action.action.as_bytes());
                    signature.bytes(action.label.as_bytes());
                    signature.bytes(action.desc.as_bytes());
                    signature.bytes(action.args.as_deref().unwrap_or_default().as_bytes());
                }
                for (index, action_id) in membership {
                    let action = &app.results[index];
                    membership_signature.number(index as u64);
                    membership_signature.bytes(action_id.as_bytes());
                    membership_signature
                        .bytes(action.args.as_deref().unwrap_or_default().as_bytes());
                    membership_signature.bytes(action.label.as_bytes());
                    membership_signature.bytes(action.desc.as_bytes());
                }
                let summary = fixture.summary.with_output_signatures(
                    Some(membership_signature.finish()),
                    Some(signature.finish()),
                );
                let (root_list_geometry, root_grid_geometry) = if grid {
                    let warm_rebuild_count = geometry_after
                        .rebuild_count
                        .saturating_sub(geometry_before.rebuild_count);
                    let warm_cells_measured = geometry_after
                        .measured_cells
                        .saturating_sub(geometry_before.measured_cells);
                    assert_eq!(
                        warm_rebuild_count, 0,
                        "warm grid frames reuse cell geometry"
                    );
                    assert_eq!(warm_cells_measured, 0, "warm grid frames measure no cells");
                    let cold_rebuild_count = mode_geometry
                        .rebuild_count
                        .saturating_sub(geometry_before_mode.rebuild_count);
                    let cold_cells_measured = mode_geometry
                        .measured_cells
                        .saturating_sub(geometry_before_mode.measured_cells);
                    assert_eq!(cold_rebuild_count, 1, "grid mode builds one geometry cache");
                    (
                        None,
                        Some(workloads::RootGridGeometrySummary {
                            cold_rebuild_count,
                            cold_cells_measured,
                            last_cold_rebuild_nanos: mode_geometry.last_rebuild_nanos,
                            warm_rebuild_count,
                            warm_cells_measured,
                        }),
                    )
                } else {
                    let warm_rebuild_count = geometry_after
                        .rebuild_count
                        .saturating_sub(geometry_before.rebuild_count);
                    let warm_rows_measured = geometry_after
                        .measured_rows
                        .saturating_sub(geometry_before.measured_rows);
                    assert_eq!(warm_rebuild_count, 0, "warm list frames reuse row geometry");
                    assert_eq!(warm_rows_measured, 0, "warm list frames measure no rows");
                    (
                        Some(workloads::RootListGeometrySummary {
                            cold_rebuild_count: cold_geometry.rebuild_count,
                            cold_rows_measured: cold_geometry.measured_rows,
                            last_cold_rebuild_nanos: cold_geometry.last_rebuild_nanos,
                            warm_rebuild_count,
                            warm_rows_measured,
                        }),
                        None,
                    )
                };
                workloads::emit_summary_with_root_geometries(
                    &format!("launcher-{count}-{scenario}"),
                    "production render_root_ui; headless run_ui lifecycle debug-test CPU",
                    summary,
                    timing,
                    &metrics,
                    root_list_geometry,
                    root_grid_geometry,
                );
            }
            drop(app);
        }
        drop(workspace);
    }

    #[test]
    fn reopening_pick_restores_previous_parking_after_its_result_was_consumed() {
        let ctx = egui::Context::default();
        let mut app = new_app(&ctx);
        app.visible_flag.store(false, Ordering::SeqCst);
        app.last_visible = false;

        let (started_tx, started_rx) = std::sync::mpsc::channel();
        let (outcomes_tx, outcomes_rx) = std::sync::mpsc::channel();
        let capture_runtime = Arc::new(CoordinateCaptureFixture {
            started: started_tx,
            outcomes: Mutex::new(outcomes_rx),
        });
        let copied = Arc::new(Mutex::new(Vec::new()));
        app.coordinate_tool =
            crate::gui::coordinate_tool::CoordinateToolGui::with_backends_and_capture(
                "settings.json".into(),
                crate::coordinate_tool::CoordinateToolPreferences::default(),
                Arc::new(crate::coordinate_tool::NativeCoordinateRuntimeFactory),
                Box::new(CoordinateClipboardFixture(Arc::clone(&copied))),
                capture_runtime,
            );

        app.begin_coordinate_pick().unwrap();
        let first = started_rx.recv_timeout(Duration::from_secs(2)).unwrap();
        let revision_before_conflicts = app.visibility_revision.current();
        assert!(app.begin_color_pick().is_err());
        assert!(app.begin_ocr_selection().is_err());
        assert!(app.start_or_focus_screen_draw().is_err());
        app.begin_crop_screenshot();
        app.begin_screen_draw_region_picker(crate::screen_draw::ScreenDrawRegionPickerReady {
            generation: crate::screen_draw::ScreenDrawGeneration::from_raw(99),
            bounds: crate::mkmacro::screen::ScreenRect::new(0, 0, 100, 100),
        });
        assert!(
            <LauncherApp as crate::commands::RadialCommandHost>::request_radial_control(
                &mut app,
                crate::radial::control::RadialControlRequest::Show(
                    crate::radial::control::RadialMenuSelector::IdOrName("Work".into()),
                ),
            )
            .is_err()
        );
        assert_eq!(app.visibility_revision.current(), revision_before_conflicts);
        assert!(app.crop_screenshot_operation.is_none());
        assert!(app.screen_draw_region_operation.is_none());
        assert!(!app.color_pick_capture_busy());
        assert!(!app.ocr_capture_busy());

        let original = crate::launcher_parking::LauncherWindowRect {
            left: 1200,
            top: 700,
            right: 1663,
            bottom: 987,
        };
        let (transaction, observer) = crate::launcher_parking::launcher_parking_test_fixture(
            1_u64,
            original,
            crate::mkmacro::screen::ScreenRect::new(0, 0, 1920, 1080),
        );
        app.coordinate_capture_parking = Some(crate::gui::coordinate_tool::CoordinatePickParking {
            transaction: Some(transaction),
            prior_visible: false,
            owned_revision: app.visibility_revision.current(),
        });
        outcomes_tx
            .send(crate::coordinate_tool::CaptureOutcome::Captured(
                crate::coordinate_tool::CoordinateSample::new(
                    crate::coordinate_tool::PhysicalPoint::new(91, -27),
                    None,
                    None,
                    None,
                ),
            ))
            .unwrap();

        // Model completion arriving before the next command: the adapter may
        // consume the result first, while LauncherApp still owns parking.
        let deadline = std::time::Instant::now() + Duration::from_secs(2);
        while app.coordinate_tool.capture_pending() && std::time::Instant::now() < deadline {
            app.coordinate_tool.poll_capture();
            thread::yield_now();
        }
        assert!(!app.coordinate_tool.capture_pending());
        assert!(app.coordinate_capture_parking.is_some());
        assert_eq!(*copied.lock().unwrap(), ["91,-27"]);

        app.begin_coordinate_pick().unwrap();
        let second = started_rx.recv_timeout(Duration::from_secs(2)).unwrap();
        assert_ne!(first, second);
        assert_eq!(observer.restored_rects(), [original]);
        assert!(
            app.coordinate_capture_parking
                .as_ref()
                .is_some_and(|state| state.transaction.is_none()),
            "the new lifecycle must own fresh parking state only after the old restore"
        );

        app.cancel_coordinate_pick();
        outcomes_tx
            .send(crate::coordinate_tool::CaptureOutcome::Cancelled)
            .unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(2);
        while app.coordinate_tool.capture_pending() && std::time::Instant::now() < deadline {
            app.poll_coordinate_pick(&ctx);
            thread::yield_now();
        }
        assert!(!app.coordinate_tool.capture_pending());
        app.coordinate_tool.shutdown().unwrap();
    }

    #[test]
    fn coordinate_pick_restore_failure_blocks_reopen_and_other_capture_admission() {
        let ctx = egui::Context::default();
        let mut app = new_app(&ctx);
        app.visible_flag.store(false, Ordering::SeqCst);
        app.last_visible = false;

        let (started_tx, started_rx) = std::sync::mpsc::channel();
        let (outcomes_tx, outcomes_rx) = std::sync::mpsc::channel();
        app.coordinate_tool =
            crate::gui::coordinate_tool::CoordinateToolGui::with_backends_and_capture(
                "settings.json".into(),
                crate::coordinate_tool::CoordinateToolPreferences::default(),
                Arc::new(crate::coordinate_tool::NativeCoordinateRuntimeFactory),
                Box::new(CoordinateClipboardFixture(Arc::new(Mutex::new(Vec::new())))),
                Arc::new(CoordinateCaptureFixture {
                    started: started_tx,
                    outcomes: Mutex::new(outcomes_rx),
                }),
            );

        app.begin_coordinate_pick().unwrap();
        started_rx.recv_timeout(Duration::from_secs(2)).unwrap();
        let original = crate::launcher_parking::LauncherWindowRect {
            left: 1200,
            top: 700,
            right: 1663,
            bottom: 987,
        };
        let (transaction, observer) = crate::launcher_parking::launcher_parking_test_fixture(
            2_u64,
            original,
            crate::mkmacro::screen::ScreenRect::new(0, 0, 1920, 1080),
        );
        app.coordinate_capture_parking = Some(crate::gui::coordinate_tool::CoordinatePickParking {
            transaction: Some(transaction),
            prior_visible: false,
            owned_revision: app.visibility_revision.current(),
        });
        outcomes_tx
            .send(crate::coordinate_tool::CaptureOutcome::Captured(
                crate::coordinate_tool::CoordinateSample::new(
                    crate::coordinate_tool::PhysicalPoint::new(91, -27),
                    None,
                    None,
                    None,
                ),
            ))
            .unwrap();

        let deadline = std::time::Instant::now() + Duration::from_secs(2);
        while app.coordinate_tool.capture_pending() && std::time::Instant::now() < deadline {
            app.coordinate_tool.poll_capture();
            thread::yield_now();
        }
        assert!(!app.coordinate_tool.capture_pending());

        observer.fail_next_restore();
        app.poll_coordinate_pick(&ctx);
        assert!(app.coordinate_capture_parking.is_some());
        assert!(observer.restored_rects().is_empty());
        assert!(app.ensure_no_coordinate_pick().is_err());
        assert!(app.ensure_coordinate_pick_admitted().is_err());
        assert!(app.begin_color_pick().is_err());
        assert!(app.begin_ocr_selection().is_err());
        assert!(app.start_or_focus_screen_draw().is_err());
        assert!(
            <LauncherApp as crate::commands::RadialCommandHost>::request_radial_control(
                &mut app,
                crate::radial::control::RadialControlRequest::Show(
                    crate::radial::control::RadialMenuSelector::IdOrName("Work".into()),
                ),
            )
            .is_err()
        );

        observer.fail_next_restore();
        assert!(app.begin_coordinate_pick().is_err());
        assert!(app.coordinate_capture_parking.is_some());
        assert!(started_rx.try_recv().is_err());
        assert!(observer.restored_rects().is_empty());

        app.begin_coordinate_pick().unwrap();
        started_rx.recv_timeout(Duration::from_secs(2)).unwrap();
        assert_eq!(observer.restored_rects(), [original]);

        app.cancel_coordinate_pick();
        outcomes_tx
            .send(crate::coordinate_tool::CaptureOutcome::Cancelled)
            .unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(2);
        while app.coordinate_tool.capture_pending() && std::time::Instant::now() < deadline {
            app.poll_coordinate_pick(&ctx);
            thread::yield_now();
        }
        assert!(!app.coordinate_tool.capture_pending());
        app.coordinate_tool.shutdown().unwrap();
    }

    struct CoordinateCaptureFixture {
        started: std::sync::mpsc::Sender<crate::coordinate_tool::CaptureSessionId>,
        outcomes: Mutex<std::sync::mpsc::Receiver<crate::coordinate_tool::CaptureOutcome>>,
    }

    impl crate::coordinate_tool::CaptureRuntime for CoordinateCaptureFixture {
        fn run_session(
            &self,
            session_id: crate::coordinate_tool::CaptureSessionId,
            _control: crate::coordinate_tool::capture::CaptureControl,
            updates: crate::coordinate_tool::capture::CaptureUpdatePublisher,
        ) -> crate::coordinate_tool::CaptureOutcome {
            let _ =
                updates.publish_phase(crate::coordinate_tool::CapturePhase::WaitingForFreshClick);
            let _ = self.started.send(session_id);
            self.outcomes.lock().unwrap().recv().unwrap_or_else(|_| {
                crate::coordinate_tool::CaptureOutcome::Failed("fixture closed".into())
            })
        }
    }

    #[derive(Clone)]
    struct CoordinateClipboardFixture(Arc<Mutex<Vec<String>>>);

    impl crate::gui::coordinate_tool::CoordinateClipboardWriter for CoordinateClipboardFixture {
        fn set_text(&mut self, text: &str) -> anyhow::Result<()> {
            self.0.lock().unwrap().push(text.to_owned());
            Ok(())
        }
    }

    fn new_prompt_app(ctx: &egui::Context) -> (LauncherApp, tempfile::TempDir) {
        let directory = tempfile::tempdir().unwrap();
        let actions_path = directory.path().join("actions.json");
        let settings_path = directory.path().join("settings.json");
        let app = LauncherApp::new(
            ctx,
            Arc::new(Vec::new()),
            0,
            PluginManager::new(),
            actions_path.display().to_string(),
            settings_path.display().to_string(),
            Settings::default(),
            None,
            None,
            None,
            None,
            Arc::new(AtomicBool::new(false)),
            Arc::new(AtomicBool::new(false)),
            Arc::new(AtomicBool::new(false)),
        );
        (app, directory)
    }

    struct StartupCaptureBackend {
        capture_calls: AtomicUsize,
        completed: std::sync::mpsc::Sender<()>,
    }

    impl crate::screen_draw::capture::DesktopCaptureBackend for StartupCaptureBackend {
        fn virtual_desktop(&self) -> Result<crate::mkmacro::screen::ScreenRect, String> {
            Ok(crate::mkmacro::screen::ScreenRect::new(
                -1920, -1080, 5760, 3240,
            ))
        }

        fn capture_desktop(
            &self,
            cancelled: &dyn Fn() -> bool,
        ) -> Result<crate::mkmacro::screen::CapturedRegion, String> {
            assert!(!cancelled());
            self.capture_calls.fetch_add(1, Ordering::SeqCst);
            let _ = self.completed.send(());
            Ok(crate::mkmacro::screen::CapturedRegion {
                image: image::RgbaImage::from_pixel(4, 3, image::Rgba([1, 2, 3, 255])),
                origin: (-1920, -1080),
            })
        }
    }

    struct ParkedLauncherProbe;

    impl crate::screen_draw::capture::LauncherVisibilityProbe for ParkedLauncherProbe {
        fn launcher_is_capture_parked(
            &self,
            launcher_hwnd: Option<usize>,
            virtual_desktop: crate::mkmacro::screen::ScreenRect,
        ) -> Result<bool, String> {
            assert_eq!(launcher_hwnd, Some(42));
            assert_eq!(
                virtual_desktop,
                crate::mkmacro::screen::ScreenRect::new(-1920, -1080, 5760, 3240)
            );
            Ok(true)
        }
    }

    struct StartupNativeFactory {
        spawns: AtomicUsize,
        command_receivers:
            Mutex<Vec<std::sync::mpsc::Receiver<crate::screen_draw::NativeSessionCommand>>>,
    }

    impl crate::screen_draw::native_runtime::NativeSessionFactory for StartupNativeFactory {
        fn spawn(
            &self,
            config: crate::screen_draw::native_runtime::NativeSessionConfig,
        ) -> Result<crate::screen_draw::NativeSessionHandle, String> {
            assert_eq!(config.snapshot.capture().origin, (-1920, -1080));
            self.spawns.fetch_add(1, Ordering::SeqCst);
            let (handle, commands, events) =
                crate::screen_draw::NativeSessionHandle::test_stub_with_events();
            events
                .send(crate::screen_draw::NativeSessionEvent::SessionStarted(
                    crate::screen_draw::NativeRuntimeState {
                        mode: crate::screen_draw::ScreenDrawMode::Drawing,
                        tool: config.tool,
                        color: config.color,
                        thickness: config.thickness,
                        annotations_visible: true,
                        background: config.settings.default_background,
                    },
                ))
                .expect(
                    "startup fixture publishes its configured runtime through the worker queue",
                );
            self.command_receivers.lock().unwrap().push(commands);
            Ok(handle)
        }
    }

    #[test]
    fn screen_draw_start_keeps_root_alive_across_parking_capture_native_and_toolbar() {
        let ctx = egui::Context::default();
        let mut app = new_app(&ctx);
        let (capture_completed, capture_completed_rx) = std::sync::mpsc::channel();
        let capture = Arc::new(StartupCaptureBackend {
            capture_calls: AtomicUsize::new(0),
            completed: capture_completed,
        });
        let native = Arc::new(StartupNativeFactory {
            spawns: AtomicUsize::new(0),
            command_receivers: Mutex::new(Vec::new()),
        });
        app.screen_draw_controller =
            crate::screen_draw::ScreenDrawController::with_test_dependencies(
                capture.clone(),
                Arc::new(ParkedLauncherProbe),
                native.clone(),
            );
        app.screen_draw_controller
            .set_recovery_bridge(Arc::clone(&app.screen_draw_recovery_bridge));
        app.launcher_hwnd = Some(42);
        install_owned_root_for_test(&mut app);
        app.static_location_enabled = true;
        app.follow_mouse = true;

        assert!(app.start_or_focus_screen_draw().unwrap());
        let generation = app.screen_draw_controller.state().generation().unwrap();
        let original = crate::launcher_parking::LauncherWindowRect {
            left: 1371,
            top: 611,
            right: 1834,
            bottom: 898,
        };
        let desktop = crate::mkmacro::screen::ScreenRect::new(-1920, -1080, 5760, 3240);
        let (transaction, observer) =
            crate::launcher_parking::launcher_parking_test_fixture(generation, original, desktop);
        app.screen_draw_launcher_parking = Some(transaction);

        // Reproduce the old invocation-bearing owner before normal parking.
        // The normal production parking request must clear it; observation
        // must neither copy that old trace owner nor advance restore history.
        while app.visibility_revision.current() < 114 {
            app.visibility_revision
                .request_with_focus_intent_and_invocation(
                    crate::visibility::RootFocusIntent::ActivateRoot,
                    Some(124),
                    || app.visible_flag.store(true, Ordering::SeqCst),
                );
        }
        assert_eq!(app.visibility_revision.current(), 114);
        assert_eq!(app.visibility_revision.invocation_id(), Some(124));

        ctx.begin_pass(egui::RawInput::default());
        app.poll_screen_draw_capture(&ctx);
        assert!(matches!(
            app.screen_draw_controller.state(),
            crate::screen_draw::ScreenDrawState::AwaitingLauncherParking { .. }
        ));
        assert!(!app.visible_flag.load(Ordering::SeqCst));

        app.poll_screen_draw_capture(&ctx);
        assert!(matches!(
            app.screen_draw_controller.state(),
            crate::screen_draw::ScreenDrawState::Capturing { .. }
        ));
        assert!(!app.screen_draw_controller.toolbar_open());
        capture_completed_rx
            .recv_timeout(Duration::from_secs(5))
            .expect("capture worker completes without blocking the GUI thread");

        for _ in 0..100_000 {
            app.poll_screen_draw_capture(&ctx);
            if matches!(
                app.screen_draw_controller.state(),
                crate::screen_draw::ScreenDrawState::Drawing { .. }
            ) {
                break;
            }
            std::thread::yield_now();
        }
        assert_eq!(
            app.screen_draw_controller.state(),
            &crate::screen_draw::ScreenDrawState::Drawing { generation }
        );
        // Capture completion precedes the native worker's queued startup event.
        assert!(app.screen_draw_controller.runtime_state().is_none());
        app.poll_screen_draw_capture(&ctx);
        assert_eq!(
            app.screen_draw_controller
                .runtime_state()
                .expect("the normal poll consumes the worker's startup event")
                .mode,
            crate::screen_draw::ScreenDrawMode::Drawing
        );
        assert!(app.screen_draw_controller.toolbar_open());
        assert_eq!(capture.capture_calls.load(Ordering::SeqCst), 1);
        assert_eq!(native.spawns.load(Ordering::SeqCst), 1);
        assert_eq!(app.visibility_revision.current(), 115);
        assert_eq!(app.visibility_revision.invocation_id(), None);
        let publication_before = format!("{:?}", app.screen_draw_restore_publication);
        let current =
            super::super::screen_draw_toolbar::retained_current_launcher_observation_for_test(
                &mut app,
                crate::screen_draw::window_layers::ToolbarObservationIdentity {
                    hwnd: 51,
                    process_id: std::process::id(),
                    client_size: [264, 700],
                },
            )
            .expect("real retained Drawing Responses publish their actual current owner");
        assert_eq!(current.launcher.visibility_revision, 115);
        assert_eq!(current.launcher.invocation_id, None);
        assert!(!current.launcher.visible);
        assert_eq!(current.launcher.root.unwrap().hwnd, 42);
        assert_eq!(
            current.launcher.root.unwrap().process_id,
            std::process::id()
        );
        assert_eq!(
            current.launcher.root.unwrap().generation,
            app.root_window_bridge.identity().1
        );
        let parking = current.launcher.parking.unwrap();
        assert_eq!(parking.hwnd, 42);
        assert_eq!(parking.generation, generation.get());
        assert_eq!(parking.cycle, 1);
        assert_eq!(
            parking.state,
            crate::radial::acceptance_trace::ScreenDrawParkingState::Committed
        );
        assert!(current.has_visible_controls_for_mode(
            crate::radial::acceptance_trace::ScreenDrawToolbarMode::Drawing
        ));
        assert_eq!(
            format!("{:?}", app.screen_draw_restore_publication),
            publication_before
        );
        assert_eq!(app.visibility_revision.current(), 115);
        app.show_screen_draw_toolbar(&ctx);
        let output = ctx.end_pass();

        assert!(app.screen_draw_toolbar.was_open);
        assert!(observer.restored_rects().is_empty());
        let root_commands = &output
            .viewport_output
            .get(&egui::ViewportId::ROOT)
            .expect("root viewport remains in the frame")
            .commands;
        assert!(!root_commands.iter().any(|command| matches!(
            command,
            egui::ViewportCommand::Visible(false) | egui::ViewportCommand::Minimized(true)
        )));
        output.drop_without_applying_deltas();
    }

