    #[test]
    fn root_escape_cancels_pre_capture_and_restores_without_generic_placement() {
        let ((), scheduled) = crate::window_manager::with_launcher_restore_queue_for_test(|| {
            for capturing in [false, true] {
                let ctx = egui::Context::default();
                let mut app = new_app(&ctx);
                ctx.begin_pass(egui::RawInput::default());
                ctx.end_pass().drop_without_applying_deltas();
                assert!(app.start_or_focus_screen_draw().unwrap());
                let generation = app.screen_draw_controller.state().generation().unwrap();
                assert!(!app.start_or_focus_screen_draw().unwrap());
                assert!(!app.screen_draw_controller.toolbar_open());
                if capturing {
                    app.screen_draw_controller
                        .launcher_parked(generation)
                        .unwrap();
                }
                let (observer, original) = install_recovery_parking(&mut app, generation);

                ctx.begin_pass(egui::RawInput {
                    events: vec![key_press(egui::Key::Escape, egui::Modifiers::NONE)],
                    ..Default::default()
                });
                app.cancel_screen_draw_startup_on_escape(&ctx);
                let output = ctx.end_pass();

                assert_eq!(
                    app.screen_draw_controller.state(),
                    &crate::screen_draw::ScreenDrawState::NoSession
                );
                assert_eq!(observer.restored_rects(), [original]);
                assert!(app.screen_draw_launcher_parking.is_none());
                assert!(app.visible_flag.load(Ordering::SeqCst));
                assert!(app.last_visible);
                assert!(!app.restore_flag.load(Ordering::SeqCst));
                let commands = &output
                    .viewport_output
                    .get(&egui::ViewportId::ROOT)
                    .unwrap()
                    .commands;
                assert!(!commands.iter().any(|command| matches!(
                    command,
                    egui::ViewportCommand::Visible(false) | egui::ViewportCommand::Minimized(true)
                )));
            }
        });
        #[cfg(windows)]
        {
            assert_eq!(scheduled.len(), 2);
            assert_root_activation_evidence(&scheduled);
        }
    }

    #[test]
    fn typed_parking_effect_synchronizes_visibility_without_configured_hide() {
        let ctx = egui::Context::default();
        let mut app = new_app(&ctx);
        ctx.begin_pass(egui::RawInput::default());
        ctx.end_pass().drop_without_applying_deltas();
        let generation = app.screen_draw_controller.request_start().unwrap();
        let original = crate::launcher_parking::LauncherWindowRect {
            left: 25,
            top: 40,
            right: 425,
            bottom: 240,
        };
        let (transaction, observer) = crate::launcher_parking::launcher_parking_test_fixture(
            generation,
            original,
            crate::mkmacro::screen::ScreenRect::new(0, 0, 1920, 1080),
        );
        app.screen_draw_launcher_parking = Some(transaction);
        app.visible_flag.store(true, Ordering::SeqCst);
        app.last_visible = true;
        app.restore_flag.store(true, Ordering::SeqCst);

        ctx.begin_pass(egui::RawInput::default());
        app.apply_screen_draw_capture_poll(
            &ctx,
            crate::screen_draw::ScreenDrawCapturePoll {
                park_launcher: Some(crate::screen_draw::ScreenDrawParkingRequest {
                    generation,
                    virtual_desktop: crate::mkmacro::screen::ScreenRect::new(0, 0, 1920, 1080),
                }),
                ..Default::default()
            },
        );
        let output = ctx.end_pass();

        assert!(!app.visible_flag.load(Ordering::SeqCst));
        assert!(!app.last_visible);
        assert!(!app.restore_flag.load(Ordering::SeqCst));
        assert!(app.screen_draw_launcher_parking.is_some());
        assert!(observer.restored_rects().is_empty());
        let commands = &output
            .viewport_output
            .get(&egui::ViewportId::ROOT)
            .unwrap()
            .commands;
        assert!(!commands.iter().any(|command| matches!(
            command,
            egui::ViewportCommand::Visible(false) | egui::ViewportCommand::Minimized(true)
        )));
    }

    #[test]
    fn stale_parking_effect_cannot_mutate_replacement_generation() {
        let ctx = egui::Context::default();
        let mut app = new_app(&ctx);
        let first = app.screen_draw_controller.request_start().unwrap();
        let second = app.screen_draw_controller.request_new_capture().unwrap();
        assert_ne!(first, second);

        app.apply_screen_draw_capture_poll(
            &ctx,
            crate::screen_draw::ScreenDrawCapturePoll {
                park_launcher: Some(crate::screen_draw::ScreenDrawParkingRequest {
                    generation: first,
                    virtual_desktop: crate::mkmacro::screen::ScreenRect::new(0, 0, 1920, 1080),
                }),
                ..Default::default()
            },
        );

        assert_eq!(
            app.screen_draw_controller.state(),
            &crate::screen_draw::ScreenDrawState::AwaitingLauncherParking { generation: second }
        );
        assert!(app.screen_draw_launcher_parking.is_none());
    }

    fn two_results() -> Vec<Action> {
        (0..2)
            .map(|index| Action {
                label: format!("Result {index}"),
                desc: "Test".into(),
                action: format!("test:{index}"),
                args: None,
            })
            .collect()
    }

    fn key_press(key: egui::Key, modifiers: egui::Modifiers) -> egui::Event {
        egui::Event::Key {
            key,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers,
        }
    }

    #[test]
    fn launcher_scope_shortcuts_require_root_query_ownership_and_leave_modal_keys_alone() {
        for (
            first_pass,
            query_focus,
            action_sheet,
            ocr,
            confirmation,
            file_search,
            diff_open,
            key,
            expected,
        ) in [
            (
                true,
                true,
                false,
                false,
                false,
                false,
                false,
                egui::Key::Num4,
                Some(crate::search_scope::SearchScope::Notes),
            ),
            (false, true, false, false, false, false, false, egui::Key::Num3, None),
            (true, false, false, false, false, false, false, egui::Key::Num3, None),
            (true, true, true, false, false, false, false, egui::Key::Num3, None),
            (true, true, false, true, false, false, false, egui::Key::Num3, None),
            // Confirmation windows retain the ROOT query's previous focus.
            (true, true, false, false, true, false, false, egui::Key::Num3, None),
            (true, true, false, false, false, true, false, egui::Key::Num3, None),
            // Ctrl+1 and Ctrl+2 belong to the diff text view while it is open.
            (true, true, false, false, false, false, true, egui::Key::Num1, None),
            (true, true, false, false, false, false, true, egui::Key::Num2, None),
        ] {
            let ctx = egui::Context::default();
            ctx.begin_pass(egui::RawInput {
                events: vec![key_press(key, egui::Modifiers::CTRL)],
                ..Default::default()
            });
            let (actual, event_still_available) = ctx.input_mut(|input| {
                let scope = consume_launcher_search_scope_shortcut(
                    first_pass,
                    query_focus,
                    action_sheet,
                    ocr,
                    confirmation,
                    file_search,
                    diff_open,
                    input,
                );
                (scope, input.consume_key(egui::Modifiers::CTRL, key))
            });
            ctx.end_pass().drop_without_applying_deltas();
            assert_eq!(actual, expected);
            assert_eq!(event_still_available, expected.is_none());
        }
    }

    #[test]
    fn launcher_scope_new_session_reset_is_one_activation_edge_only() {
        use crate::visibility::RootFocusIntent;

        assert!(LauncherApp::should_reset_search_scope_for_new_session(
            false,
            true,
            RootFocusIntent::ActivateRoot,
        ));
        assert!(!LauncherApp::should_reset_search_scope_for_new_session(
            false,
            true,
            RootFocusIntent::PreserveForeground,
        ));
        assert!(!LauncherApp::should_reset_search_scope_for_new_session(
            true,
            true,
            RootFocusIntent::ActivateRoot,
        ));
        assert!(!LauncherApp::should_reset_search_scope_for_new_session(
            false,
            false,
            RootFocusIntent::ActivateRoot,
        ));
    }

    #[test]
    fn snippet_origin_capture_follows_activation_even_without_new_session() {
        use crate::visibility::RootFocusIntent;

        assert!(LauncherApp::should_reset_search_scope_for_new_session(
            false,
            true,
            RootFocusIntent::ActivateRoot,
        ));
        assert!(
            LauncherApp::should_capture_snippet_origin_before_root_activation(
                true,
                RootFocusIntent::ActivateRoot,
            )
        );

        // An already-visible ROOT can be backgrounded. Its explicit restore is
        // still an activation boundary even though the search session continues.
        assert!(!LauncherApp::should_reset_search_scope_for_new_session(
            true,
            true,
            RootFocusIntent::ActivateRoot,
        ));
        assert!(
            LauncherApp::should_capture_snippet_origin_before_root_activation(
                true,
                RootFocusIntent::ActivateRoot,
            )
        );
        assert!(
            !LauncherApp::should_capture_snippet_origin_before_root_activation(
                true,
                RootFocusIntent::PreserveForeground,
            )
        );
        assert!(
            !LauncherApp::should_capture_snippet_origin_before_root_activation(
                false,
                RootFocusIntent::ActivateRoot,
            )
        );
    }

